 *
 * This test ensures:
 * - The admin endpoint returns a list including all members registered in the system.
 * - The listing includes every member created during setup with all key details (id, user_identifier, joined_at, suspended_at).
 * - Each member’s data in the result is accurate and matches what was used at creation.
 *
 * Steps:
 * 1. Create several members via the admin creation endpoint (using unique user_identifiers and joined_at times).
 * 2. Call the admin listing endpoint to retrieve all board members.
 * 3. Assert that each setup member appears in the paginated listing with correct properties.
 * 4. Validate that at least the number of created members is present, and that the list item’s fields (id, user_identifier, joined_at, suspended_at) reflect creation-time values.
 */
export async function test_api_discussionBoard_admin_members_index(
  connection: api.IConnection,
) {
  // Step 1: Create several new board members (as admin)
  const setupMembers: IDiscussionBoardMember[] = await ArrayUtil.asyncRepeat(3)(async () => {
    const user_identifier = RandomGenerator.alphaNumeric(10);
    const joined_at = new Date().toISOString();
    const member = await api.functional.discussionBoard.admin.members.create(connection, {
      body: {
        user_identifier,
        joined_at,
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    return member;
