/**
 * Audit log creation validation test (required fields).
 *
 * This test attempts to create a new audit log record as an administrator, but intentionally omits one or more required fields (such as 'action_type').
 * The system should reject these requests and return a validation error to ensure business rules are enforced. The purpose is to verify that all mandatory audit details are required by the API and no audit log can be created with missing essentials.
 *
 * Steps:
 * 1. Try to create a log with missing 'action_type' (should fail)
 * 2. Try to create a log with only 'action_type' (should succeed)
 * 3. Try to create a log omitting optional fields (should succeed if business rules allow)
 * 4. Try to create a log with both 'action_type' and all other fields populated (should succeed)
 */
export async function test_api_discussionBoard_admin_auditLogs_create_validation(
  connection: api.IConnection,
) {
  // 1. Attempt to create a log without action_type (required): should fail
  await TestValidator.error("missing action_type should fail")(async () => {
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: {
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        target_id: typia.random<string & tags.Format<"uuid">>(),
        // action_type is intentionally omitted
        action_detail: "Tried to create log without required action_type field.",
      },
    });
  });

  // 2. Minimal valid creation: only action_type present, other fields omitted or null
  const minimalLog = await api.functional.discussionBoard.admin.auditLogs.create(connection, {
    body: {
      action_type: "assign_moderator",
      // optional fields omitted
    },
  });
  typia.assert(minimalLog);
  TestValidator.equals("action_type present")(minimalLog.action_type)("assign_moderator");

  // 3. Create a log with optional fields set to null
  const nullFieldsLog = await api.functional.discussionBoard.admin.auditLogs.create(connection, {
    body: {
      action_type: "policy_change",
      actor_id: null,
      target_id: null,
      action_detail: null,
    },
  });
  typia.assert(nullFieldsLog);
  TestValidator.equals("action_type present")(nullFieldsLog.action_type)("policy_change");
  TestValidator.equals("actor_id is null")(nullFieldsLog.actor_id)(null);
  TestValidator.equals("target_id is null")(nullFieldsLog.target_id)(null);
  TestValidator.equals("action_detail is null")(nullFieldsLog.action_detail)(null);

  // 4. Create a log with all fields populated (should succeed)
  const completeLog = await api.functional.discussionBoard.admin.auditLogs.create(connection, {
    body: {
      action_type: "user_ban",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
