  // 1. Register a new board member (admin action)
  const now = new Date().toISOString();
  const memberInput: IDiscussionBoardMember.ICreate = {
    user_identifier: RandomGenerator.alphaNumeric(12),
    joined_at: now,
  };
  const member = await api.functional.discussionBoard.admin.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Member subscribes to a target (simulate a topic subscription with random UUID)
  const SUBSCRIPTION_TARGET_TYPES = ['topic', 'thread'];
  const target_type = RandomGenerator.pick(SUBSCRIPTION_TARGET_TYPES);
  const target_id = typia.random<string & tags.Format<'uuid'>>();
