 *   - For each omitted field, assert that an error is thrown and the API does not return a successful record.
 * 2. Attempt to create with negative values or non-integral numbers for counts (post_count, comment_count, active_user_count, report_count).
 *   - For each count field, try negative values and floating-points; assert error thrown and creation rejected.
 * 3. Attempt empty-string for dimension and segment_value; expect error response.
 * 4. For all validation error scenarios, assert that the API throws an error (do not inspect error message details, only that error occurs).
 */
export async function test_api_discussionBoard_admin_engagementStats_create_test_create_engagement_stat_with_missing_or_invalid_fields_fails(connection: api.IConnection) {
  // Helper: valid payload
  const valid: IDiscussionBoardEngagementStat.ICreate = {
    period_start: typia.random<string & tags.Format<"date-time">>(),
    period_end: typia.random<string & tags.Format<"date-time">>(),
    dimension: "site",
    segment_value: "admin",
    post_count: 10,
    comment_count: 5,
    active_user_count: 2,
    report_count: 1,
  };

