  for (const key of ["dimension", "segment_value"]) {
    const input = { ...valid, [key]: "" };
    await TestValidator.error("empty string " + key)(async () => {
      await api.functional.discussionBoard.admin.engagementStats.create(connection, { body: input });
    });
  }
}

