import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * Verify that an ordinary member cannot view details of a system notice that is NOT currently visible due to inactivity, expiry, or scheduled future exposure.
 *
 * Business context: Only active and currently-valid system notices should be accessible by discussion board members. Notices that are inactive (is_active=false), already expired (end_at < now), or scheduled for future (start_at > now) must NOT be accessible to a member by /member/systemNotices/{systemNoticeId}, returning an error or hidden state.
 *
 * The test will proceed as follows:
 * 1. Create (as admin) a system notice that is INACTIVE (is_active=false), or active but scheduled outside the current time window (start_at in the far future or end_at in the past).
 * 2. Try to fetch that notice as a member using the member endpoint.
 * 3. Expect an error or access denial (e.g., 404 Not Found) for these hidden notices.
 * 4. As a control, create (as admin) an ACTIVE system notice with a present time window, and confirm the member CAN retrieve it.
 */
export async function test_api_discussionBoard_test_retrieve_inactive_or_scheduled_notice_as_member_fails(connection: api.IConnection) {
  // 1. Create INACTIVE system notice (should be hidden from members)
  const inactiveNotice = await api.functional.discussionBoard.admin.systemNotices.create(connection, {
    body: {
      title: 'Inactive Notice',
      body: 'This notice is not visible to members',
      is_active: false,
      start_at: null,
      end_at: null,
      category_id: null,
    }
  });
  typia.assert(inactiveNotice);

  // 2. Member tries to fetch inactive notice (should fail)
  await TestValidator.error('Inactive system notice must not be accessible to member')(async () => {
    await api.functional.discussionBoard.member.systemNotices.at(connection, {
      systemNoticeId: inactiveNotice.id,
    });
  });

  // 3. Create FUTURE-scheduled active notice (should be hidden from members)
  const futureDate = new Date(Date.now() + 1000 * 60 * 60 * 24 * 3).toISOString(); // 3 days in the future
  const futureNotice = await api.functional.discussionBoard.admin.systemNotices.create(connection, {
    body: {
      title: 'Future Notice',
      body: 'This notice is scheduled for the future',
      is_active: true,
      start_at: futureDate,
      end_at: null,
      category_id: null,
    }
  });
  typia.assert(futureNotice);

  await TestValidator.error('Future-scheduled system notice must not be accessible to member')(async () => {
    await api.functional.discussionBoard.member.systemNotices.at(connection, {
      systemNoticeId: futureNotice.id,
    });
  });

  // 4. Create EXPIRED notice (should be hidden from members)
  const pastDate = new Date(Date.now() - 1000 * 60 * 60 * 24 * 3).toISOString(); // 3 days in the past
  const expiredNotice = await api.functional.discussionBoard.admin.systemNotices.create(connection, {
    body: {
      title: 'Expired Notice',
      body: 'This notice has already expired',
      is_active: true,
      start_at: null,
      end_at: pastDate,
      category_id: null,
    }
  });
  typia.assert(expiredNotice);

  await TestValidator.error('Expired system notice must not be accessible to member')(async () => {
    await api.functional.discussionBoard.member.systemNotices.at(connection, {
      systemNoticeId: expiredNotice.id,
    });
  });

  // 5. Create ACTIVE and currently-visible notice (should succeed)
  const visibleNotice = await api.functional.discussionBoard.admin.systemNotices.create(connection, {
    body: {
      title: 'Visible Notice',
      body: 'This notice should be visible to members',
      is_active: true,
      start_at: null,
      end_at: null,
      category_id: null,
    }
  });
  typia.assert(visibleNotice);

  // Member can successfully fetch it
  const fetchedNotice = await api.functional.discussionBoard.member.systemNotices.at(connection, {
    systemNoticeId: visibleNotice.id,
  });
  typia.assert(fetchedNotice);
  TestValidator.equals('visible notice id')(fetchedNotice.id)(visibleNotice.id);
}

