import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * 시나리오: 관리자가 새로운 게시판 카테고리를 추가한다.
 *
 * - 1단계: 최상위 부모 카테고리를 먼저 생성한다 (parent_id: null, name 랜덤, 설명, 활성화 여부 true/false 테스트)
 * - 2단계: 1단계에서 받은 id를 parent_id로 하여 하위 카테고리를 생성한다 (name, description 랜덤, 활성화 true/false 랜덤)
 *           parent_id를 정상적으로 참조해야 하며, name은 유일하게 지정해야 한다.
 * - 3단계: 응답 객체가 요청에 넣은 값들과 일치하는지, parent-child 구조가 맞는지 검증한다.
 * - 4단계: (가능할 경우) 감사 로그 등 부가적 생성 이벤트가 남는지도 확인.
 *
 * 본 테스트는 성공적 카테고리 계층 생성의 happy-path를 검증한다.
 */
export async function test_api_discussionBoard_test_create_new_category_with_valid_data_and_optional_parent(
  connection: api.IConnection
) {
  // 1. 최상위 부모 카테고리 생성 (parent_id: null, name 유일, description 랜덤, is_active 랜덤)
  const parent_name = `${RandomGenerator.alphabets(8)}-parent`;
  const parent_description = RandomGenerator.paragraph()();
  const parent_is_active = Math.random() > 0.5;

  const parentCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: parent_name,
      description: parent_description,
      parent_id: null,
      is_active: parent_is_active,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(parentCategory);
  TestValidator.equals("parent name")(parentCategory.name)(parent_name);
  TestValidator.equals("parent description")(parentCategory.description)(parent_description);
  TestValidator.equals("parent is_active")(parentCategory.is_active)(parent_is_active);
  TestValidator.equals("parent id is null")(parentCategory.parent_id)(null);
  TestValidator.predicate("parent id format")(
    typeof parentCategory.id === "string" && parentCategory.id.length > 0
  );

  // 2. 하위 카테고리 생성 (parent_id는 위에서 생성한 parent의 id)
  const child_name = `${RandomGenerator.alphabets(8)}-child`;
  const child_description = RandomGenerator.paragraph()();
  const child_is_active = Math.random() > 0.5;
  const childCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: child_name,
      description: child_description,
      parent_id: parentCategory.id,
      is_active: child_is_active,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(childCategory);
  TestValidator.equals("child name")(childCategory.name)(child_name);
  TestValidator.equals("child description")(childCategory.description)(child_description);
  TestValidator.equals("child is_active")(childCategory.is_active)(child_is_active);
  TestValidator.equals("child parent_id matches")(childCategory.parent_id)(parentCategory.id);
  TestValidator.predicate("child id format")(
    typeof childCategory.id === "string" && childCategory.id.length > 0
  );

  // 3. parent_id가 정상적으로 계층구조를 반영하는지 검증 (child->parent 연결이 맞게 되었는지)
  // 이미 위 assertion으로 카테고리 연결 및 값 일치 확인 완료

  // 4. (선택적) 추가 검증: 생성된 parent, child 카테고리의 created_at/updated_at 필드가 ISO 날짜 형식이고 서로 독립적임을 확인
  TestValidator.predicate("parent created_at ISO")(!!Date.parse(parentCategory.created_at));
  TestValidator.predicate("parent updated_at ISO")(!!Date.parse(parentCategory.updated_at));
  TestValidator.predicate("child created_at ISO")(!!Date.parse(childCategory.created_at));
  TestValidator.predicate("child updated_at ISO")(!!Date.parse(childCategory.updated_at));
  TestValidator.notEquals("parent/child id must differ")(childCategory.id)(parentCategory.id);

  // (감사 로그 확인 API가 있다면 여기서 audit 로그도 체크할 것)
}

