 */
export async function test_api_discussionBoard_test_get_discussion_board_category_details_when_category_exists(connection: api.IConnection) {
  // 1. Create a root category via admin
  const rootCreate: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphaNumeric(12),
    description: RandomGenerator.paragraph()(),
    parent_id: null,
    is_active: true,
  };
  const rootCategory = await api.functional.discussionBoard.admin.categories.create(connection, { body: rootCreate });
  typia.assert(rootCategory);

  // 2. Create a nested child category via admin
  const childCreate: IDiscussionBoardCategory.ICreate = {
    name: RandomGenerator.alphaNumeric(10),
    description: RandomGenerator.paragraph()(),
