  TestValidator.equals("root name matches")(fetchedRoot.name)(rootCreate.name);
  TestValidator.equals("root description matches")(fetchedRoot.description)(rootCreate.description ?? null);
  TestValidator.equals("root parent is null")(fetchedRoot.parent_id)(null);
  TestValidator.equals("root is_active matches")(fetchedRoot.is_active)(rootCreate.is_active);

  // 4. Fetch child category by ID
