  TestValidator.equals("child parent matches root")(fetchedChild.parent_id)(rootCategory.id);
  TestValidator.equals("child is_active matches")(fetchedChild.is_active)(childCreate.is_active);

  // 5. Optionally, call again as a guest to ensure public access (if test runner allows, otherwise skip)
}

