import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test that advanced moderator search using grant and revoked date ranges works as intended.
 *
 * This test creates multiple moderator entries:
 * - At least one moderator with active status (granted, not revoked)
 * - At least one moderator with a revoked status (grant timestamp in the past, revoked timestamp set)
 *
 * It then performs advanced searches using combinations of the following filters:
 * - granted_at_from / granted_at_to
 * - revoked_at_from / revoked_at_to
 * - Only active (revoked_at is null)
 * - Only revoked (revoked_at is between date range)
 *
 * For each search, verify that only moderators matching the query (grant/revoke status and ranges) are returned in the paged result. Validate correct inclusion/exclusion.
 */
export async function test_api_discussionBoard_admin_moderators_test_advanced_search_moderators_by_revoked_status(
  connection: api.IConnection,
) {
  // 1. Create a currently active moderator entry
  const grantTimeActive = new Date(Date.now() - 24 * 3600 * 1000).toISOString(); // yesterday
  const activeModerator = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        user_identifier: `active-user-${typia.random<string>()}`,
        granted_at: grantTimeActive,
        revoked_at: null,
      }
    },
  );
  typia.assert(activeModerator);

  // 2. Create a revoked moderator entry
  const grantTimeRevoked = new Date(Date.now() - 7 * 24 * 3600 * 1000).toISOString(); // 7 days ago
  const revokeTime = new Date(Date.now() - 2 * 24 * 3600 * 1000).toISOString(); // 2 days ago
  const revokedModerator = await api.functional.discussionBoard.admin.moderators.create(
    connection,
    {
      body: {
        user_identifier: `revoked-user-${typia.random<string>()}`,
        granted_at: grantTimeRevoked,
        revoked_at: revokeTime,
      }
    },
  );
  typia.assert(revokedModerator);

  // 3. Search for all active moderators (revoked_at is null)
  let result = await api.functional.discussionBoard.admin.moderators.search(
    connection,
    {
      body: {
        revoked_at_from: null,
        revoked_at_to: null,
        granted_at_from: null,
        granted_at_to: null,
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(result);
  TestValidator.predicate("includes just active moderator")(result.data.some((m) => m.id === activeModerator.id));
  TestValidator.predicate("does not include revoked moderator")(result.data.every((m) => m.id !== revokedModerator.id));

  // 4. Search for moderators revoked in last 3 days
  result = await api.functional.discussionBoard.admin.moderators.search(
    connection,
    {
      body: {
        revoked_at_from: new Date(Date.now() - 3 * 24 * 3600 * 1000).toISOString(),
        revoked_at_to: new Date().toISOString(),
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(result);
  TestValidator.predicate("includes revoked moderator")(result.data.some((m) => m.id === revokedModerator.id));
  TestValidator.predicate("does not include active moderator")(result.data.every((m) => m.id !== activeModerator.id));

  // 5. Search with granted_at window for active moderator
  result = await api.functional.discussionBoard.admin.moderators.search(
    connection,
    {
      body: {
        granted_at_from: new Date(Date.now() - 2 * 24 * 3600 * 1000).toISOString(),
        granted_at_to: new Date().toISOString(),
        page: 1,
        limit: 10,
      },
    },
  );
  typia.assert(result);
  TestValidator.predicate("active moderator included by grant time")(result.data.some((m) => m.id === activeModerator.id));
}

