  const createLogs = ArrayUtil.asyncRepeat(logCount)(async (i) => {
    const entryTime = new Date(baseDate.getTime() - i * 60000); // i분씩 시간 차이
    return await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
