  // 5. 삭제 성공 여부를 비즈니스 로직상과 별도 Assertion
  // hard-delete이므로, 재삭제 시 not-found와 같은 에러 발생하는지 확인
  await TestValidator.error('재삭제 시도 시 not-found 등 오류 발생해야 함')(async () => {
    await api.functional.discussionBoard.admin.activityLogs.erase(connection, {
      activityLogId: createdLog.id
    });
  });
  // 별도의 감사 로그 검증은 관련 API가 제공되지 않으므로 생략
}

