import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";
import type { IPageIDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSubscription";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 관리자 권한으로 다양한 조건(구독자, 대상 유형, 알림 방식 등)이 혼합된 구독 데이터를 생성한 후,
 * PATCH(/discussionBoard/admin/subscriptions)를 통해 고급 필터 및 페이징 기능이 의도대로 동작하는지 검증합니다.
 *
 * [테스트 흐름]
 * 1. 여러 명의 가상 유저 UUID와 여러 개의 가상 토픽/스레드(각각 uuid, 타입 분리)의 구독 데이터를 생성합니다 (POST 이용).
 * 2. 각기 다른 필터(구독자 user 필터, 대상 타입별 필터, 알림 방식별, 활성/비활성 상태, 시간 범위 등)를 조합해 검색 요청을 여러 번 수행합니다.
 * 3. 페이징 처리 검증(예: limit 2로 쿼리하여 여러 페이지, 페이지 이동 등 검증)
 * 4. 모든 결과가 실제 생성된 데이터와 일치하는지, 요청 조건 별로 정확히 필터링되는지 각 쿼리마다 확인합니다.
 */
export async function test_api_discussionBoard_admin_subscriptions_test_admin_filter_and_paginate_subscriptions(
  connection: api.IConnection,
) {
  // 1. 다양한 구독 테스트 데이터 생성 (3명의 유저 * 4개 타입/타겟 * 2개 알림 방식 = 24건)
  const userIds = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const topics = ArrayUtil.repeat(2)(() => ({ type: "topic" as const, id: typia.random<string & tags.Format<"uuid">>() }));
  const threads = ArrayUtil.repeat(2)(() => ({ type: "thread" as const, id: typia.random<string & tags.Format<"uuid">>() }));
  const notificationMethods = ["email", "in-app"];

  // 최근 시간 순으로 생성 시간 보장
  const now = new Date();

  const created: IDiscussionBoardSubscription[] = [];
  for (const userId of userIds) {
    for (const target of [...topics, ...threads]) {
      for (const method of notificationMethods) {
        const active = Math.random() < 0.5;
        const subscribed_at = new Date(now.getTime() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000)).toISOString(); // 최근 30일 내 랜덤
        const subscription = await api.functional.discussionBoard.admin.subscriptions.create(connection, {
          body: {
            subscriber_id: userId,
            target_type: target.type,
            target_id: target.id,
            notification_method: method,
            is_active: active,
          } satisfies IDiscussionBoardSubscription.ICreate,
        });
        // 일부 데이터의 시간만 최신으로, 일부만 비활성으로
        subscription.subscribed_at = subscribed_at;
        created.push(subscription);
      }
    }
  }

  // 2-a. 구독자 UUID 별 필터 확인
  for (const userId of userIds) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        subscriber_id: userId,
      } satisfies IDiscussionBoardSubscription.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("subscriber_id filter 동작")(output.data.every(row => row.subscriber_id === userId));
  }

  // 2-b. target_type 필터(토픽)
  for (const targetType of ["topic", "thread"]) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        target_type: targetType,
      },
    });
    typia.assert(output);
    TestValidator.predicate(`${targetType}만 추출됨`)(output.data.every(row => row.target_type === targetType));
  }

  // 2-c. notification_method 필터
  for (const method of notificationMethods) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        notification_method: method,
      },
    });
    typia.assert(output);
    TestValidator.predicate(`${method}만 추출됨`)(output.data.every(row => row.notification_method === method));
  }

  // 2-d. is_active 필터
  for (const isActive of [true, false]) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        is_active: isActive,
      },
    });
    typia.assert(output);
    TestValidator.predicate(`${isActive ? "활성화" : "비활성화"} 구독만 추출됨`)(output.data.every(row => row.is_active === isActive));
  }

  // 2-e. 기간 조건 (subscribed_at_from ~ to)
  const fromDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString();
  const toDate = now.toISOString();
  const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
    body: {
      subscribed_at_from: fromDate,
      subscribed_at_to: toDate,
    },
  });
  typia.assert(output);
  TestValidator.predicate("7일 내 구독만 반환됨")(output.data.every(row => row.subscribed_at >= fromDate && row.subscribed_at <= toDate));

  // 3. 페이징 검증 (limit=2, page=1/2/3)
  const pagingLimit = 2;
  let page = 1;
  let totalCount = 0;
  const seenIds = new Set<string>();
  while (true) {
    const pageOutput = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        limit: pagingLimit,
        page,
      },
    });
    typia.assert(pageOutput);
    if (pageOutput.data.length === 0) break;
    totalCount += pageOutput.data.length;
    for (const row of pageOutput.data) seenIds.add(row.id);
    page++;
    if (page > 10) break; // 과도한 반복 방지
  }
  TestValidator.equals("모든 id set 갯수가 전체와 일치")(seenIds.size)(created.length);
}

