  for (const userId of userIds) {
    for (const target of [...topics, ...threads]) {
      for (const method of notificationMethods) {
        // 활성화 상태 랜덤 분포, 가입시간 최근 ~ 한달 이내 랜덤 시점
        const active = Math.random() < 0.5;
        const subscribed_at = new Date(now.getTime() - Math.floor(Math.random() * 30 * 24 * 60 * 60 * 1000)).toISOString();
        const subscription = await api.functional.discussionBoard.admin.subscriptions.create(connection, {
          body: {
            subscriber_id: userId,
            target_type: target.type,
            target_id: target.id,
            notification_method: method,
            is_active: active,
          } satisfies IDiscussionBoardSubscription.ICreate,
        });
        // 테스트 편의상 시간 필드를 저장해두고, 아래 기간 필터 쿼리에서 사용
        subscription.subscribed_at = subscribed_at;
        created.push(subscription);
      }
    }
  }

  // ---------- 2-a. 구독자별 필터 테스트 ----------
  for (const userId of userIds) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        subscriber_id: userId,
      } satisfies IDiscussionBoardSubscription.IRequest,
    });
    typia.assert(output);
    TestValidator.predicate("subscriber_id 필터 동작")(output.data.every(row => row.subscriber_id === userId));
  }

  // ---------- 2-b. 대상 타입별(topic/thread) 필터 테스트 ----------
  for (const targetType of ["topic", "thread"]) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        target_type: targetType,
      },
    });
    typia.assert(output);
    TestValidator.predicate(`${targetType} 필터 동작")(output.data.every(row => row.target_type === targetType));
  }

  // ---------- 2-c. 알림방식별 필터 테스트 ----------
  for (const method of notificationMethods) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        notification_method: method,
      },
    });
    typia.assert(output);
    TestValidator.predicate(`${method} 필터 동작")(output.data.every(row => row.notification_method === method));
  }

  // ---------- 2-d. 활성/비활성별 필터 테스트 ----------
  for (const isActive of [true, false]) {
    const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        is_active: isActive,
      },
    });
    typia.assert(output);
    TestValidator.predicate(`${isActive ? "활성화" : "비활성화"} 필터 동작")(output.data.every(row => row.is_active === isActive));
  }

  // ---------- 2-e. 기간별(subscribed_at_from ~ to) 필터 테스트 ----------
  const fromDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString();
  const toDate = now.toISOString();
  const output = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
    body: {
      subscribed_at_from: fromDate,
      subscribed_at_to: toDate,
    },
  });
  typia.assert(output);
  TestValidator.predicate("7일 이내 가입 구독만 반환")(output.data.every(row => row.subscribed_at >= fromDate && row.subscribed_at <= toDate));

  // ---------- 3. 페이징 동작 검증 (limit=2)
  const pagingLimit = 2;
  let page = 1;
  let totalCount = 0;
  const seenIds = new Set<string>();
  while (true) {
    const pageOutput = await api.functional.discussionBoard.admin.subscriptions.search(connection, {
      body: {
        limit: pagingLimit,
        page,
      },
    });
    typia.assert(pageOutput);
    if (pageOutput.data.length === 0) break; // 데이터 끝
    totalCount += pageOutput.data.length;
    for (const row of pageOutput.data) seenIds.add(row.id);
    page++;
    if (page > 10) break; // 과도한 반복 방지
  }
  TestValidator.equals("전체 생성 데이터와 unique id 갯수 일치")(seenIds.size)(created.length);
}

