/**
 * Validate advanced search/filter for board members by admin.
 *
 * This test ensures the admin can:
 * 1. Search for members by suspension status
 * 2. Search by partial/full user_identifier
 * 3. Use pagination and have results match filter and paging settings
 *
 * Workflow:
 * 1. Create a mix of active and suspended members (suspended = suspended_at !== null)
 * 2. Search for only suspended members, confirm all results are suspended.
 * 3. Search for only active members, confirm all results are active.
 * 4. Search for a member by unique user_identifier, ensure only the correct member is returned.
 * 5. Test pagination: create enough users for multiple pages (e.g. 8+), search with small limit (e.g. 3/page), and verify correct number of records and that paging metadata matches the actual data count.
 */
export async function test_api_discussionBoard_test_search_members_by_status_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create diverse members: 4 suspended, 4 active, varying user_identifier
  const identifiers: string[] = ArrayUtil.repeat(8)(() => RandomGenerator.alphaNumeric(8));
  const joinedAtList: string[] = ArrayUtil.repeat(8)(() => new Date(Date.now() - RandomGenerator.integer(0)(60*60*24*10*1000)).toISOString());
  // Alternate suspension
  const memberRecords: IDiscussionBoardMember[] = [];
  for (let i = 0; i < 8; ++i) {
    const member = await api.functional.discussionBoard.admin.members.create(connection, {
      body: {
        user_identifier: identifiers[i],
        joined_at: joinedAtList[i],
      } satisfies IDiscussionBoardMember.ICreate,
    });
    typia.assert(member);
    // Simulate suspension: if i < 4, we set suspended_at field (admin scenario may require extra endpoint; if not present, leave for validation)
    memberRecords.push(i < 4 ? { ...member, suspended_at: new Date().toISOString() } : member);
  }

  // 2. Search for suspended members
  const suspendedResult = await api.functional.discussionBoard.admin.members.search(connection, {
    body: {
      suspended: true,
      limit: 10,
      page: 1,
    } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(suspendedResult);
  TestValidator.predicate("all suspended")(suspendedResult.data.every(m => m.suspended_at != null));

  // 3. Search for active members
  const activeResult = await api.functional.discussionBoard.admin.members.search(connection, {
    body: {
      suspended: false,
      limit: 10,
      page: 1,
    } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(activeResult);
  TestValidator.predicate("all active")(activeResult.data.every(m => !m.suspended_at));

  // 4. Search by unique user_identifier
  const searchIdentifier = identifiers[0];
  const byIdentifierResult = await api.functional.discussionBoard.admin.members.search(connection, {
    body: {
      user_identifier: searchIdentifier,
    } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(byIdentifierResult);
  TestValidator.predicate("identifier search result")(byIdentifierResult.data.length === 1 && byIdentifierResult.data[0].user_identifier === searchIdentifier);

  // 5. Test pagination
  const pageLimit = 3;
  // Page 1
  const page1 = await api.functional.discussionBoard.admin.members.search(connection, {
    body: {
      limit: pageLimit,
      page: 1,
    } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(page1);
  TestValidator.equals("pagination page1 count")(page1.data.length)(pageLimit);
  TestValidator.equals("pagination meta page1")(page1.pagination.current)(1);
  // Page 2
  const page2 = await api.functional.discussionBoard.admin.members.search(connection, {
    body: {
      limit: pageLimit,
      page: 2,
    } satisfies IDiscussionBoardMember.IRequest,
  });
  typia.assert(page2);
  TestValidator.equals("pagination page2 count")(page2.data.length)(pageLimit);
  TestValidator.equals("pagination meta page2")(page2.pagination.current)(2);
  // Last page
