 *
 * 테스트 단계:
 * 1. 정상 관리자 계정에서 필수·권장값을 모두 입력해 활동 로그 생성 성공을 확인
 * 2. 필수 입력 누락(예: actor_id 없음)시 런타임 에러 확인
 * 3. 존재하지 않는 actor_id, 또는 유효하지 않은 참조값 입력 시 에러 확인
 * 4. 관리자 권한 없는(비인증) 상태에서 요청 시 에러 확인
 *
 * 부가적으로, 생성한 로그의 주요 필드와 감사 목적의 저장 여부, 스키마 유효성(assert)까지 검증
 */
export async function test_api_discussionBoard_test_create_activity_log_admin_success_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 관리자 계정에서 정상 입력으로 활동 로그 생성 성공
  const now = new Date().toISOString();
  const actorId = typia.random<string & tags.Format<"uuid">>();
  const logInput: IDiscussionBoardActivityLog.ICreate = {
    actor_id: actorId,
    actor_type: "admin",
    action_type: "board_locked",
    action_timestamp: now,
    ip_address: "192.168.0.1",
    user_agent: "Mozilla/5.0 (E2E-Test)",
    topic_id: typia.random<string & tags.Format<"uuid">>(),
    thread_id: null,
    post_id: null,
    metadata_json: JSON.stringify({ reason: "Test E2E log", severity: "high" }),
  };
  const createdLog = await api.functional.discussionBoard.admin.activityLogs.create(connection, {
    body: logInput,
  });
  typia.assert(createdLog);
  TestValidator.equals("actor reference")(createdLog.actor_id)(actorId);
  TestValidator.equals("type matches")(createdLog.actor_type)("admin");
  TestValidator.equals("action matches")(createdLog.action_type)("board_locked");
  TestValidator.equals("timestamp matches")(createdLog.action_timestamp)(now);

  // 2. 필수 입력값 누락(actor_id 없음) - 런타임 오류
  await TestValidator.error("require actor_id fail")(async () => {
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        ...logInput,
        actor_id: undefined as any,
      },
    });
  });

  // 3. 존재하지 않는 actor_id 입력(가정: 시스템에 없는 actor UUID) - 에러 기대
  await TestValidator.error("nonexistent actor_id fail")(async () => {
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        ...logInput,
        actor_id: "11111111-1111-1111-1111-111111111111" as any,
      },
    });
  });

  // 4. 비인증 요청(관리자 인증 없이 시도) - connection에서 인증헤더 삭제 후 시도
  const noAuthConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete noAuthConnection.headers["Authorization"];
  await TestValidator.error("unauthorized fail")(async () => {
    await api.functional.discussionBoard.admin.activityLogs.create(noAuthConnection, {
      body: logInput,
    });
  });
}

