import type { IDiscussionBoardNotification } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardNotification";

/**
 * Validate that an admin user can successfully delete their own notification.
 *
 * 1. First, create a notification addressed to the admin user (the acting admin is the recipient).
 * 2. Delete the notification as the admin via the DELETE /discussionBoard/admin/notifications/{notificationId} endpoint.
 * 3. Attempt to retrieve the deleted notification as a member (using GET /discussionBoard/member/notifications/{notificationId}) and confirm that it no longer exists (should fail or return not found).
 * 4. (Not technically verifiable via current API, but describe expectation that the system audits this deletion operation.)
 */
export async function test_api_discussionBoard_test_admin_delete_own_notification_success(
  connection: api.IConnection,
) {
  // 1. Create a notification for the admin (using the admin context)
  const recipientId: string = typia.random<string & tags.Format<"uuid">>();
  const now: string = new Date().toISOString();
  const notification = await api.functional.discussionBoard.admin.notifications.create(
    connection,
    {
      body: {
        recipient_id: recipientId,
        notification_type: "system",
        target_type: "thread",
        target_id: typia.random<string & tags.Format<"uuid">>(),
        message: "System maintenance notification.",
        delivered_at: now,
        delivery_status: "delivered"
      } satisfies IDiscussionBoardNotification.ICreate
    }
  );
  typia.assert(notification);

  // 2. Delete the notification as admin
  await api.functional.discussionBoard.admin.notifications.erase(
    connection,
    { notificationId: notification.id }
  );

  // 3. Try to retrieve the notification as a member (should fail)
  await TestValidator.error("Notification must be deleted and not retrievable")(
    async () => {
      await api.functional.discussionBoard.member.notifications.at(
