import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdmin";
import type { IPageIDiscussionBoardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching for discussion board admins using both active state and grant date window filters.
 *
 * Business context:
 * Admin listing/pivot and privilege audit panels must accurately filter admins based on 'currently active' (revoked_at=null)
 * and those whose grant (assignment) happened in a specific period. This is essential for compliance, privilege reviews, and
 * behavioral analysis on the management platform.
 *
 * Test steps:
 * 1. Create several admin records with distinct grant/revoked_at timestamps:
 *    - Some with revoked_at=null (active), others with revoked_at set (inactive)
 *    - Spread grant dates across a window before/during/after the filter period
 * 2. Formulate a search request with:
 *    - granted_at_from/granted_at_to spanning a window that covers only some created records
 *    - revoked_at_from/revoked_at_to unset (not used in this test)
 * 3. Send the PATCH /discussionBoard/admin/admins request for search
 * 4. Assert:
 *    - All returned admins are active (revoked_at is null)
 *    - All have grant (granted_at) inside the period (inclusive)
 *    - No extra records are present
 *    - Paging and data structure are as expected
 * 5. Edge: Test a second page if enough records exist (pagination)
 */
export async function test_api_discussionBoard_admin_admins_test_search_admins_by_active_state_and_granted_date_range(
  connection: api.IConnection,
) {
  // 1. Create admins with different states and grant/revoke dates
  const now = new Date();
  const pastWindowStart = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 30); // 30 days ago
  const pastWindowEnd = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 15);    // 15 days ago
  const filterStart = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 20);      // 20 days ago
  const filterEnd = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 10);        // 10 days ago

  // Example admins:
  // - adminA: grant inside filter, active
  // - adminB: grant before filter, active
  // - adminC: grant inside filter, revoked later (inactive)
  // - adminD: grant after filter, active

  // Create eligible admin (in filter, active)
  const adminInFilterActive = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      user_identifier: RandomGenerator.alphabets(8),
      granted_at: filterStart.toISOString(),
      revoked_at: null
    }
  });
  typia.assert(adminInFilterActive);

  // Create non-matching (before filter, active)
  const adminBeforeFilterActive = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      user_identifier: RandomGenerator.alphabets(8),
      granted_at: pastWindowStart.toISOString(),
      revoked_at: null
    }
  });
  typia.assert(adminBeforeFilterActive);

  // Create eligible (in filter, revoked = inactive)
  const adminInFilterRevoked = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      user_identifier: RandomGenerator.alphabets(8),
      granted_at: filterEnd.toISOString(),
      revoked_at: now.toISOString()
    }
  });
  typia.assert(adminInFilterRevoked);

  // Create non-matching (after filter, active)
  const adminAfterFilterActive = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      user_identifier: RandomGenerator.alphabets(8),
      granted_at: pastWindowEnd.toISOString(),
      revoked_at: null
    }
  });
  typia.assert(adminAfterFilterActive);

  // 2. Search for active admins granted within filter period
  const searchResult = await api.functional.discussionBoard.admin.admins.search(connection, {
    body: {
      granted_at_from: filterStart.toISOString(),
      granted_at_to: filterEnd.toISOString(),
      revoked_at_from: null,
      revoked_at_to: null,
      user_identifier: null,
      page: 1,
      limit: 100
    }
  });
  typia.assert(searchResult);

  // 3. Validate all returned admins:
  // - revoked_at is null (active)
  // - granted_at within window
  for (const admin of searchResult.data) {
    TestValidator.equals('revoked_at is null')(admin.revoked_at)(null);
    TestValidator.predicate('granted_at in filter window')(
      admin.granted_at >= filterStart.toISOString() &&
      admin.granted_at <= filterEnd.toISOString()
    );
  }

  // 4. Validate pagination structure
  TestValidator.equals('page')(searchResult.pagination.current)(1);
  TestValidator.equals('limit')(searchResult.pagination.limit)(100);
  TestValidator.predicate('pages positive')(searchResult.pagination.pages > 0);
  TestValidator.predicate('records nonnegative')(searchResult.pagination.records >= searchResult.data.length);

  // 5. Only admins matching BOTH: revoked_at is null AND grant in window, should be present
  const expectedUids = [adminInFilterActive.user_identifier];
  TestValidator.equals('returned count')(searchResult.data.length)(expectedUids.length);
  for (const rec of searchResult.data) {
    TestValidator.predicate('data expected')(expectedUids.includes(rec.user_identifier));
  }
}

