import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSetting";
import type { IPageIDiscussionBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSetting";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 고급 설정 키 부분일치 검색 기능을 검증합니다.
 *
 * 1. 서로 다른 키로 몇 가지 설정을 미리 생성합니다 (예: "feature_toggle_X", "theme_option_Y", "global_policy_Z").
 * 2. "option" 같은 일부 문자열을 포함하는 키로만 걸러내는 부분일치 검색을 PATCH로 시도합니다.
 * 3. 결과로 반환된 각 setting에 대해 모두 setting_key에 그 부분 문자열이 포함되어 있는지 검증합니다.
 * 4. 동시에 페이지네이션 검증을 위해 limit: 1로 요청, 첫 결과만 반환되는지 pagination 필드도 확인합니다.
 */
export async function test_api_discussionBoard_test_advanced_search_settings_by_key_substring_returns_correct_results(
  connection: api.IConnection,
) {
  // 1. 설정 데이터 여러 개 생성 (feature_toggle_X, theme_option_Y, global_policy_Z 식별 가능하도록 각각 구분)
  const prefixList = ["feature_toggle_A", "theme_option_B", "theme_option_C", "global_policy_D"];
  const createdSettings: IDiscussionBoardSetting[] = [];
  for (const key of prefixList) {
    const setting = await api.functional.discussionBoard.admin.settings.create(connection, {
      body: {
        setting_key: key,
        setting_value: RandomGenerator.alphaNumeric(8),
        description: `설정 key: ${key}`,
      } satisfies IDiscussionBoardSetting.ICreate,
    });
    typia.assert(setting);
    createdSettings.push(setting);
  }

  // 2. 부분 문자열 'option'이 포함된 설정만 검색 (키: theme_option_B, theme_option_C만 나와야 함)
  const substring = "option";
  const searchOutput = await api.functional.discussionBoard.admin.settings.search(connection, {
    body: {
      setting_key: substring,
    } satisfies IDiscussionBoardSetting.IRequest,
  });
  typia.assert(searchOutput);

  // 3. 반환된 각 setting_key가 부분 문자열을 포함하는지 검증
  for (const item of searchOutput.data) {
    TestValidator.predicate(`setting_key 포함 substring 검사 (${item.setting_key})`)(
      item.setting_key.includes(substring),
    );
  }
  // 3-1. 실제 결과 건수와 예상 filter 결과 건수 비교
  const expectCount = createdSettings.filter(s => s.setting_key.includes(substring)).length;
  TestValidator.equals("filter 결과 건수 일치")(
    searchOutput.data.length,
  )(
    expectCount,
  );

  // 4. 페이징 결과 확인: limit 1 지정 시, 한 건만
  const pageOutput = await api.functional.discussionBoard.admin.settings.search(connection, {
    body: {
      setting_key: substring,
      limit: 1,
      page: 1,
    } satisfies IDiscussionBoardSetting.IRequest,
  });
  typia.assert(pageOutput);
  TestValidator.equals("limit=1 범위 결과 건수 확인")(pageOutput.data.length)(1);
  // pagination 메타데이터 검증
  TestValidator.equals("pagination.limit 일치")(pageOutput.pagination.limit)(1);
  TestValidator.equals("pagination.current 일치")(pageOutput.pagination.current)(1);
  TestValidator.equals("pagination.records 일치")(pageOutput.pagination.records)(expectCount);
}

