import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";

/**
 * Validate that a comment owner can retrieve full metadata details for a specific attachment on their comment.
 *
 * Business context:
 * When a member uploads an attachment to their comment, all attachment metadata (file URI, file name, MIME type, uploader ID, and timestamps) should be retrievable. This ensures auditing, ownership, and integrity of file assets.
 *
 * Steps:
 * 1. Create a new comment as a member (using the member's ID and a parent post's ID -- both must be valid UUIDs, but for test we may randomize these).
 * 2. Upload an attachment to the created comment, supplying file URI, name, MIME type, and uploader's ID. Capture the returned attachment info (including IDs and timestamps).
 * 3. As the same member (the comment owner/uploader), call the API to retrieve details for the specific attachment by commentId and attachmentId.
 * 4. Validate the response: all metadata fields (id, discussion_board_comment_id, uploader_member_id, file_name, file_url, mime_type, uploaded_at) match what was stored, and that the returned object conforms to schema.
 *
 * Edge cases (omitted due to input constraints): non-owner access, mismatched IDs, deleted attachment, etc. Only owner happy path is tested here.
 */
export async function test_api_discussionBoard_test_get_comment_attachment_detail_member_owner(connection: api.IConnection) {
  // 1. Create random UUIDs to act as parent post ID and uploader/member ID.
  const discussion_board_member_id = typia.random<string & tags.Format<"uuid">>();
  const discussion_board_post_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a new comment as the member
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_member_id,
      discussion_board_post_id,
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(comment);
  TestValidator.equals("member ID matches")(comment.discussion_board_member_id)(discussion_board_member_id);
  TestValidator.equals("post ID matches")(comment.discussion_board_post_id)(discussion_board_post_id);

  // 3. Upload an attachment to the created comment (as the member/uploader)
  const file_name = RandomGenerator.alphaNumeric(10);
  const file_url = `https://files.example.com/${RandomGenerator.alphaNumeric(20)}`;
  const mime_type = "image/png"; // Use a common image type
  const attachment_create_input = {
    discussion_board_comment_id: comment.id,
    uploader_member_id: discussion_board_member_id,
    file_name,
    file_url,
    mime_type,
  } satisfies IDiscussionBoardCommentAttachment.ICreate;
  const attachment = await api.functional.discussionBoard.member.comments.attachments.create(connection, {
    commentId: comment.id,
    body: attachment_create_input,
  });
  typia.assert(attachment);
  TestValidator.equals("comment ID matches")(attachment.discussion_board_comment_id)(comment.id);
  TestValidator.equals("uploader matches")(attachment.uploader_member_id)(discussion_board_member_id);
  TestValidator.equals("file name matches")(attachment.file_name)(file_name);
  TestValidator.equals("file url matches")(attachment.file_url)(file_url);
  TestValidator.equals("mime type matches")(attachment.mime_type)(mime_type);

  // 4. Retrieve the attachment metadata via the GET endpoint
  const output = await api.functional.discussionBoard.member.comments.attachments.at(connection, {
    commentId: comment.id,
    attachmentId: attachment.id,
  });
  typia.assert(output);
  // Verify all metadata fields match exactly
  TestValidator.equals("attachment id matches")(output.id)(attachment.id);
  TestValidator.equals("comment id matches")(output.discussion_board_comment_id)(comment.id);
  TestValidator.equals("uploader matches")(output.uploader_member_id)(discussion_board_member_id);
  TestValidator.equals("file name matches")(output.file_name)(file_name);
  TestValidator.equals("file url matches")(output.file_url)(file_url);
  TestValidator.equals("mime type matches")(output.mime_type)(mime_type);
  // Timestamp can be checked for ISO string validity with typia.assert
  typia.assert< string & tags.Format<"date-time"> >(output.uploaded_at);
}

