  const memberInput: IDiscussionBoardMember.ICreate = {
    user_identifier: typia.random<string>(),
    joined_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const member = await api.functional.discussionBoard.admin.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. Log out to simulate guest (remove Authorization header)
  const guestConnection = { ...connection, headers: { ...connection.headers } };
  delete guestConnection.headers["Authorization"];

  // 3. As guest, expect error when accessing activity logs
  await TestValidator.error("guest denied activity logs")(() =>
    api.functional.discussionBoard.admin.activityLogs.index(guestConnection),
  );

  // 4. Log in as member (simulate by setting user credentials - omitted since no login endpoint is available)
  // If an authentication/login endpoint for members existed, it would be called here to update the connection.
  // For now, we document this limitation and skip actual member login due to lack of such endpoint.

  // 5. As member, expect error as well (since we cannot simulate login, this is not implemented here)
  // To fully test this step, a member authentication/login API would be required.
}

