  const memberInput: IDiscussionBoardMember.ICreate = {
    user_identifier: RandomGenerator.alphabets(10),
    joined_at: new Date().toISOString(),
  };
  const member = await api.functional.discussionBoard.admin.members.create(connection, { body: memberInput });
  typia.assert(member);

  // 2. As admin, create a subscription for the member
  const targetType = RandomGenerator.pick(["topic", "thread"]);
  const subscriptionInput: IDiscussionBoardSubscription.ICreate = {
    subscriber_id: member.id,
    target_type: targetType,
    target_id: typia.random<string & tags.Format<"uuid">>(),
    notification_method: RandomGenerator.pick(["email", "in-app"]),
    is_active: true,
  };
  const subscription = await api.functional.discussionBoard.admin.subscriptions.create(connection, { body: subscriptionInput });
  typia.assert(subscription);

  // 3. Assert subscription record is associated with the right member and fields
  TestValidator.equals("subscriber ID matches")(subscription.subscriber_id)(member.id);
  TestValidator.equals("target_type matches")(subscription.target_type)(subscriptionInput.target_type);
  TestValidator.equals("target_id matches")(subscription.target_id)(subscriptionInput.target_id);
  TestValidator.equals("notification_method matches")(subscription.notification_method)(subscriptionInput.notification_method);
  TestValidator.equals("is_active true")(subscription.is_active)(true);
  TestValidator.predicate("subscribed_at is ISO string")(
    !isNaN(Date.parse(subscription.subscribed_at)),
  );
}

