  TestValidator.equals("id unchanged after update")(
    updateIdAndJoin.id
  )(createdMember.id);
  TestValidator.equals("suspended_at unchanged (retains suspension)")(
    updateIdAndJoin.suspended_at
  )(suspendTime);

  // 6. Admin clears suspension by setting suspended_at: null
  const updateReactivate = await api.functional.discussionBoard.admin.members.update(
