import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerationAction";

/**
 * Validate retrieving a specific moderation action detail by ID for a moderator.
 *
 * This test validates that after a moderator creates a moderation action
 * (for example, moderating a specific post), they can retrieve the full
 * detail record for that action using the GET endpoint with its unique
 * moderationActionId.
 *
 * - Create a new moderation action as a moderator (required as setup).
 * - Fetch the moderationActionId from the response.
 * - Retrieve the detail using the GET endpoint.
 * - Assert that all fields in the response match what was created (actor_moderator_id, target, action details, timestamps, etc).
 * - Confirm that all referenced fields (actor, target) are not null and formatted as expected.
 * - Attempt to get a moderation action with a non-existent UUID and confirm an error occurs.
 * - Attempt using an invalid UUID format and confirm an error occurs.
 * - Confirm only moderator/admin role can access this; (authorization boundary not implemented here; assumed connection simulates moderator).
 */
export async function test_api_discussionBoard_test_get_moderation_action_detail_by_id_for_moderator(
  connection: api.IConnection,
) {
  // 1. Create a moderation action as a moderator
  const createBody: IDiscussionBoardModerationAction.ICreate = {
    actor_moderator_id: typia.random<string & tags.Format<"uuid">>(),
    post_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "delete",
    action_details: "Automated test moderation action."
  };

  const created: IDiscussionBoardModerationAction = await api.functional.discussionBoard.moderator.moderationActions.create(connection, {
    body: createBody,
  });
  typia.assert(created);

  // 2. Retrieve the detail by the returned moderationActionId
  const fetched: IDiscussionBoardModerationAction = await api.functional.discussionBoard.moderator.moderationActions.at(connection, {
    moderationActionId: created.id,
  });
  typia.assert(fetched);

  // 3. Validate that returned fields match what was created
  TestValidator.equals("moderationActionId matches")(fetched.id)(created.id);
  TestValidator.equals("actor_moderator_id")(fetched.actor_moderator_id)(createBody.actor_moderator_id);
  TestValidator.equals("action_type")(fetched.action_type)(createBody.action_type);
  TestValidator.equals("action_details")(fetched.action_details)(createBody.action_details);
  TestValidator.equals("post_id")(fetched.post_id)(createBody.post_id);

  // actor_admin_id, comment_id, report_id should be null or undefined as not set.
  TestValidator.equals("actor_admin_id is unset")(("actor_admin_id" in fetched ? fetched.actor_admin_id : undefined))(undefined);
  TestValidator.equals("comment_id is unset")(("comment_id" in fetched ? fetched.comment_id : undefined))(undefined);
  TestValidator.equals("report_id is unset")(("report_id" in fetched ? fetched.report_id : undefined))(undefined);

  // created_at should exist and be a string (date-time format)
  TestValidator.predicate("created_at exists")(typeof fetched.created_at === "string" && !!fetched.created_at);

  // 4. Error: non-existent UUID
  const nonexistentId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("404 for non-existent ID")(async () => {
    await api.functional.discussionBoard.moderator.moderationActions.at(connection, {
      moderationActionId: nonexistentId,
    });
  });

  // 5. Error: invalid UUID format
  await TestValidator.error("400 for invalid UUID")(async () => {
    await api.functional.discussionBoard.moderator.moderationActions.at(connection, {
      moderationActionId: "invalid-uuid-format" as any,
    });
  });

  // (Authorization restriction would be tested in separate test; assume connection is privileged)
}

