 *   - No actor specified
 *   - Both actor_moderator_id and actor_admin_id omitted/null
 *   - Missing action_type
 *   - Missing all target references (no post_id, comment_id, or report_id)
 *   - Only action_type with every other field missing
 *
 * The test ensures each results in a validation error, that no record is created, and that
 * the API provides appropriate error feedback.
 */
export async function test_api_discussionBoard_test_create_moderation_action_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Prepare a valid moderator (dependency)
  const moderator = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      user_identifier: typia.random<string>(),
      granted_at: new Date().toISOString()
    },
  });
  typia.assert(moderator);

  // 2. No actor provided at all
  await TestValidator.error("should reject missing actor")(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        action_type: "delete",
        post_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 3. Both actor* fields present, but both null
  await TestValidator.error("should reject both actors null")(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        actor_moderator_id: null,
        actor_admin_id: null,
        action_type: "edit",
        post_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 4. Missing action_type
  await TestValidator.error("should reject missing action_type")(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        actor_moderator_id: moderator.id,
        post_id: typia.random<string & tags.Format<"uuid">>(),
      },
    })
  );

  // 5. Missing target reference (no post_id, comment_id, report_id)
  await TestValidator.error("should reject without target reference")(() =>
    api.functional.discussionBoard.admin.moderationActions.create(connection, {
      body: {
        actor_moderator_id: moderator.id,
