  const result = await api.functional.discussionBoard.moderator.contentFlags.index(connection);
  typia.assert(result);

  // 3. Assert correct empty result and pagination
  TestValidator.equals("flag data should be empty")(result.data)([]);
  TestValidator.equals("records should be zero")(result.pagination.records)(0);
  TestValidator.equals("pages should be zero or one")(result.pagination.pages)(0);
