  };
  const moderationAction = await api.functional.discussionBoard.admin.moderationActions.create(connection, { body: moderationActionInput });
  typia.assert(moderationAction);

  // 3. Switch to regular user context (simulate by removing privileged headers; if actual role switching possible, use full context swap)
  // IMPORTANT: This is a no-op if connection doesn't handle auth context; adjust as necessary for actual privilege switching.
  const memberConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined, // simulate a non-admin, possibly unauthenticated
    },
  };

