 * 1. A member creates a comment on a post (using the member endpoint).
 * 2. Multiple edits (versions) are performed, with at least one version authored by the member and others by admin or simulated moderator (all must be attributed correctly, simulating role switching by editor_member_id).
 * 3. Use the PATCH /discussionBoard/admin/comments/{commentId}/versions endpoint to:
 *    a. Retrieve all versions with no filter, verify total count and data integrity matches input edits.
 *    b. Filter by editor_member_id for both member/editor and admin, and by content substring, and by created_at range. Verify results are correctly filtered.
 *    c. Use pagination (limit/page controls as appropriate); verify limits/page counts align with number of edits and that data returned is correct per page.
 *    d. Query with an invalid page (e.g., page > total pages), confirm an error response.
 */
export async function test_api_discussionBoard_test_admin_advanced_search_and_pagination_on_comment_versions(
  connection: api.IConnection,
) {
  // 1. Create a new comment as a member
  const member_id = typia.random<string & tags.Format<"uuid">>();
  const post_id = typia.random<string & tags.Format<"uuid">>();
  const base_content = RandomGenerator.paragraph()();
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_member_id: member_id,
      discussion_board_post_id: post_id,
      content: base_content,
    }
  });
  typia.assert(comment);
  TestValidator.equals("author used")(comment.discussion_board_member_id)(member_id);
  TestValidator.equals("belongs-to-post")(comment.discussion_board_post_id)(post_id);

  // 2. Perform multiple edits (versions) attributed to different roles
  const admin_id = typia.random<string & tags.Format<"uuid">>();
  const moderator_id = typia.random<string & tags.Format<"uuid">>();

  // Edits: member, admin, moderator
  const versions = [];
  // Edit v1 (by member)
  versions.push(await api.functional.discussionBoard.admin.comments.versions.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      editor_member_id: member_id,
      content: RandomGenerator.paragraph()(),
    }
  }));
  // Edit v2 (by admin)
  versions.push(await api.functional.discussionBoard.admin.comments.versions.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      editor_member_id: admin_id,
      content: RandomGenerator.paragraph()(),
    }
  }));
  // Edit v3 (by moderator)
  versions.push(await api.functional.discussionBoard.admin.comments.versions.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      editor_member_id: moderator_id,
      content: RandomGenerator.paragraph()(),
    }
  }));
