  // Each returned version should have expected commentId
  allVersions.data.forEach(ver => TestValidator.equals("comment id match")(ver.discussion_board_comment_id)(comment.id));

  // 3b. Filter by editor_member_id (member)
  const memberOnly = await api.functional.discussionBoard.admin.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      editor_member_id: member_id
    },
  });
  typia.assert(memberOnly);
  memberOnly.data.forEach(ver => TestValidator.equals("editor filter: member")(ver.editor_member_id)(member_id));

  // filter by editor_member_id (admin)
  const adminOnly = await api.functional.discussionBoard.admin.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      editor_member_id: admin_id
    },
