  adminOnly.data.forEach(ver => TestValidator.equals("editor filter: admin")(ver.editor_member_id)(admin_id));

  // filter by content_contains (arbitrary string from edit)
  const containedText = versions[0].content.slice(0, 5);
  const containsFilter = await api.functional.discussionBoard.admin.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      content_contains: containedText,
    },
  });
  typia.assert(containsFilter);
  containsFilter.data.forEach(ver => TestValidator.predicate("content substring present")(ver.content.includes(containedText)));

  // filter by created_at_from/created_at_to
  const from = versions[0].created_at;
  const to = versions[2].created_at;
  const rangeFilter = await api.functional.discussionBoard.admin.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      created_at_from: from,
      created_at_to: to
    },
  });
  typia.assert(rangeFilter);
  rangeFilter.data.forEach(ver => {
    TestValidator.predicate("in range")(ver.created_at >= from && ver.created_at <= to);
  });

  // 3c. Paging test: set limit=1, page through all, check ordering, count, integrity
  // (simulate by repeatedly fetching with different pages if API supports page/limit)
  // Since no explicit page/limit in IRequest, assume backend handles via headers or params—skip deeper paging tests here, just count
  // 3d. Query with invalid paging (simulate with impossible filter)
  await TestValidator.error("invalid filter should error")(async () => {
    await api.functional.discussionBoard.admin.comments.versions.search(connection, {
      commentId: comment.id,
      body: {
        editor_member_id: typia.random<string & tags.Format<"uuid">>(),
        content_contains: "NON_EXISTENT_SUBSTR"
      },
    });
  });
}

