import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IPageIDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVersion";

/**
 * Validates that a comment author can retrieve full version history for their own comment.
 *
 * This test covers the end-to-end flow where:
 * 1. A board member is created (registration by admin).
 * 2. The member posts a comment to a (random) post.
 * 3. The member edits the comment multiple times, producing at least two total versions.
 * 4. The author requests version history for their comment and receives all versions, including timestamps and editor.
 *
 * Test asserts:
 * - Each version is present and in correct order.
 * - Editor member ID matches the author for every version.
 * - Content and timestamp differ per version.
 */
export async function test_api_discussionBoard_test_list_comment_versions_as_author(
  connection: api.IConnection,
) {
  // 1. Admin creates a member (author)
  const joinedAt = new Date().toISOString();
  const member = await api.functional.discussionBoard.admin.members.create(connection, {
    body: {
      user_identifier: RandomGenerator.alphabets(10),
      joined_at: joinedAt,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Member creates an original comment
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_member_id: member.id,
      discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
      content: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. Perform multiple edits to create versions
  const editContents = [RandomGenerator.paragraph()(), RandomGenerator.paragraph()()];
  for (const content of editContents) {
    const updated = await api.functional.discussionBoard.member.comments.update(connection, {
      commentId: comment.id,
      body: { content },
    });
    typia.assert(updated);
    TestValidator.equals("comment id matches")(updated.id)(comment.id);
    TestValidator.equals("author matches")(updated.discussion_board_member_id)(member.id);
    TestValidator.equals("not deleted")(updated.is_deleted)(false);
  }

  // 4. Author retrieves version history
  const versionsPage = await api.functional.discussionBoard.member.comments.versions.index(connection, {
    commentId: comment.id,
