 *
 * 테스트 단계:
 * 1. 유효한 topic이 있는지 확인합니다 (없는 경우 생성 혹은 불러오기).
 * 2. 해당 topicId를 이용해, 결과가 없을 만한 (예: 존재하지 않는 title 키워드, 생성자 등) 조건으로 thread를 검색합니다.
 * 3. 응답이 정상이고 에러가 발생하지 않으며, 리스트 data가 빈 배열([]), total count가 0임을 검증합니다.
 * 4. 페이징 메타데이터가 올바른 구조로 존재하는지 추가 검증합니다.
 */
export async function test_api_discussionBoard_test_search_threads_with_nonexistent_criteria_returns_empty(
