import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";

/**
 * 관리자 권한으로 기존 게시판 카테고리의 이름과 설명을 수정하는 시나리오를 검증한다.
 *
 * 이 테스트는 다음을 점검한다:
 * 1. 'name' 필드는 반드시 전체 카테고리 내에서 유일하게 유지되어야 하며 변경시 고유성을 검증한다.
 * 2. 'description' 수정이 정상적으로 반영되는지 확인한다.
 * 3. 수정 요청 후 응답 객체에 변경 내용이 즉시 반영되는지(원자성/일관성) 확인한다.
 * 4. 만약 감사(Audit) 로그 시스템이 존재할 경우, 해당 변경 이벤트가 적절히 기록되는지도 추가로 검증한다(별도 로깅 API가 존재하면 호출 진행).
 * 5. 모든 동작은 Admin 권한을 전제로 실행된다.
 *
 * [프로세스]
 * 1. (Given) 새로운 카테고리를 생성한다(테스트 종속 작업).
 * 2. (When) 기존 카테고리의 name, description을 새로운 값(유일 name)으로 변경 요청한다.
 * 3. (Then) 응답으로 받은 카테고리 객체에 변경된 name, description이 정상 반영됐는지 검증한다.
 * 4. (Then) categoryId, created_at 등 불변 필드는 불변임을 검증한다.
 * 5. (Then) updated_at이 갱신되었고, 변경전과 다름을 확인한다.
 */
export async function test_api_discussionBoard_admin_categories_test_update_category_name_and_description_successfully(
  connection: api.IConnection,
) {
  // 1. Given: 카테고리 신규 생성
  const originalCategory: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: "자동화테스트-원본-" + RandomGenerator.alphaNumeric(6),
      is_active: true,
      description: "기존 설명",
      parent_id: null,
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(originalCategory);

  // 2. When: name, description 수정(고유 name 생성)
  const newName: string = "자동화테스트-수정-" + RandomGenerator.alphaNumeric(8);
  const newDescription: string = "수정된 설명 - " + RandomGenerator.alphabets(10);
  const updated: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.update(connection, {
    categoryId: originalCategory.id,
    body: {
      name: newName,
      description: newDescription,
    } satisfies IDiscussionBoardCategory.IUpdate,
  });
  typia.assert(updated);

  // 3. Then: 반환 객체가 신규 정보와 일치하는지 검증
  TestValidator.equals("이름 변경됨")(updated.name)(newName);
  TestValidator.equals("설명 변경됨")(updated.description)(newDescription);
  TestValidator.equals("고유번호 불변")(updated.id)(originalCategory.id);
  TestValidator.equals("상위카테고리 불변")(updated.parent_id)(originalCategory.parent_id);
  TestValidator.equals("활성화 상태 불변")(updated.is_active)(originalCategory.is_active);

  // 4. Then: updated_at이 기존 created_at과 다르고, 변경 시각임을 확인
  TestValidator.notEquals("업데이트 시각 갱신됨")(updated.updated_at)(originalCategory.updated_at);

  // 5. Then: created_at(생성시각)은 변하지 않아야 함
  TestValidator.equals("생성시각 불변")(updated.created_at)(originalCategory.created_at);

  // (옵션) 감사로그 검사: 별도의 audit log API가 있다면 이 시점에 조회/확인 진행
}

