 * 2. Create a category to target for moderation.
 * 3. Create a moderator (to be assigned).
 * 4. Assign the moderator to the category as an admin using the target endpoint.
 * 5. Validate the assignment object, checking that ids and references are correct and that audit fields (id, created_at) are present and correct.
 */
export async function test_api_discussionBoard_test_assign_moderator_to_category_success(connection: api.IConnection) {
  // 1. Create an admin
  const adminUserId = RandomGenerator.alphaNumeric(16);
  const admin: IDiscussionBoardAdmin = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      user_identifier: adminUserId,
      granted_at: new Date().toISOString(),
      revoked_at: null,
    },
  });
  typia.assert(admin);

  // 2. Create a category
  const categoryName = RandomGenerator.alphaNumeric(12);
  const category: IDiscussionBoardCategory = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: categoryName,
      is_active: true,
      description: "Test category for moderator assignment",
      parent_id: null,
    },
  });
  typia.assert(category);

  // 3. Create a moderator
  const moderatorUserId = RandomGenerator.alphaNumeric(16);
