 *
 * For each filter combination, it checks:
 *  1. That only sessions matching the criteria are returned
 *  2. Pagination works—proper slicing of results per limit/page value
 *  3. Sorting of results by session identifier and timestamp as expected
 *
 * All API responses are asserted against the expected DTOs, and search logic is validated for both inclusion (positive matches) and exclusion (negative matches). Test covers edge cases such as null/date boundaries and overlapping/non-overlapping date ranges. In summary, this ensures advanced admin analytics and reporting workflows are robust and reliable.
 */
export async function test_api_discussionBoard_test_search_guest_sessions_with_valid_filters(
  connection: api.IConnection,
) {
  // Step 1: Create 4 guest sessions with different session_identifiers and time ranges
  const baseTime = new Date();
  const guestSessions = [] as IDiscussionBoardGuest[];
  const ids = [
    "visitor-aaa",
    "visitor-bbb",
    "visitor-ccc",
    "visitor-xyz"
  ];
  for (let i = 0; i < ids.length; ++i) {
    const session_identifier = ids[i];
    const delta = i * 2; // separate them by at least 2 hours
    const first_seen_at = new Date(baseTime.getTime() - (8 - delta) * 60 * 60 * 1000).toISOString();
    const last_seen_at = new Date(baseTime.getTime() - (8 - delta - 1) * 60 * 60 * 1000).toISOString();
    const guest = await api.functional.discussionBoard.guests.create(connection, {
      body: {
        session_identifier,
        first_seen_at,
        last_seen_at
      } satisfies IDiscussionBoardGuest.ICreate
    });
    typia.assert(guest);
    guestSessions.push(guest);
  }

  // Step 2: Search by exact session_identifier
  const targetId = guestSessions[2].session_identifier;
  const searchBySessionIdRes = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: {
      session_identifier: targetId
    } satisfies IDiscussionBoardGuest.IRequest
  });
  typia.assert(searchBySessionIdRes);
  TestValidator.equals("only matching guest session")(
    searchBySessionIdRes.data.map(x => x.session_identifier))(
    [targetId]
  );
  TestValidator.equals("pagination metadata")(
    searchBySessionIdRes.pagination.records
  )(1);

  // Step 3: Search within a date range (should include at least two sessions)
  const lower = guestSessions[1].first_seen_at;
  const upper = guestSessions[3].first_seen_at;
  const searchByDates = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: {
      first_seen_at_from: lower,
      first_seen_at_to: upper
    } satisfies IDiscussionBoardGuest.IRequest
  });
