  TestValidator.predicate("guest count matches range")(
    searchByDates.data.length >= 2 && searchByDates.data.length <= 3
  );
  for (const g of searchByDates.data) {
    TestValidator.predicate("guest in range")(
      g.first_seen_at >= lower && g.first_seen_at <= upper
    );
  }

  // Step 4: Search with pagination (limit = 2)
  const searchPaginated = await api.functional.discussionBoard.admin.guests.search(connection, {
    body: {
      limit: 2,
