import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";
import type { IPageIDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentAttachment";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the search API for comment attachments with pagination and sorting
 *
 * This test validates that the attachment search endpoint for a given comment correctly supports pagination and returns data in expected sort order.
 * The test will:
 * 1. Create a comment as a member.
 * 2. Upload more attachments than a typical default page size (default limit is assumed to be 100).
 * 3. Search for attachments without limit (should return first page, default limit).
 * 4. Search with a specific smaller limit (e.g., 10), and check returned items and page/record counts.
 * 5. Check that sorting (by upload timestamp, descending) is respected.
 * 6. Search for page 2 and check that the next batch of files is loaded (pagination works).
 * 7. Attempt an edge case: request beyond max page number, expect empty attachment data.
 */
export async function test_api_discussionBoard_test_search_comment_attachments_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Create a comment as a member
  const member_id: string = typia.random<string & tags.Format<"uuid">>();
  const post_id: string = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_member_id: member_id,
      discussion_board_post_id: post_id,
      content: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(comment);

  // 2. Upload more attachments than the default page size (assumed 100), e.g., 105 files
  const attachment_count = 105;
  const files = ArrayUtil.repeat(attachment_count)(i => ({
    discussion_board_comment_id: comment.id,
    uploader_member_id: member_id,
    file_name: `file_${i + 1}.txt`,
    file_url: `https://cdn.example.com/file_${i + 1}`,
    mime_type: "text/plain",
  }));

  let uploaded_files: IDiscussionBoardCommentAttachment[] = [];
  for (const file of files) {
    const attch = await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: file,
      },
    );
    uploaded_files.push(attch);
  }

  // Ensure files are sorted by uploaded_at DESC for checking later
  uploaded_files = [...uploaded_files].sort((a, b) => b.uploaded_at.localeCompare(a.uploaded_at));

  // 3. Search attachments without limit param – should return default (100)
  const first_page = await api.functional.discussionBoard.member.comments.attachments.search(
    connection,
    {
      commentId: comment.id,
      body: {
        comment_id: comment.id,
      },
    },
  );
  typia.assert(first_page);
  TestValidator.equals("default page size")(first_page.data.length)(100);
  TestValidator.equals("default page count")(first_page.pagination.limit)(100);
  TestValidator.equals("records total")(first_page.pagination.records)(attachment_count);
  TestValidator.equals("pages total")(first_page.pagination.pages)(2);

  // 4. Search with explicit limit = 10
  const limited_page = await api.functional.discussionBoard.member.comments.attachments.search(
    connection,
    {
      commentId: comment.id,
      body: {
        comment_id: comment.id,
        limit: 10,
      },
    },
  );
  typia.assert(limited_page);
  TestValidator.equals("limit 10")(limited_page.data.length)(10);
  TestValidator.equals("page count")(limited_page.pagination.limit)(10);
  // Data should match top 10 from sorted uploaded_files
  for (let i = 0; i < 10; ++i) {
    TestValidator.equals(`attachment match [${i}]`)(limited_page.data[i].id)(uploaded_files[i].id);
  }

  // 5. Page 2, limit 10
  const page_2 = await api.functional.discussionBoard.member.comments.attachments.search(
    connection,
    {
      commentId: comment.id,
      body: {
        comment_id: comment.id,
        limit: 10,
        page: 2,
      },
    },
  );
  typia.assert(page_2);
  TestValidator.equals("page 2 length")(page_2.data.length)(10);
  for (let i = 0; i < 10; ++i) {
    TestValidator.equals(`attachment match page2 [${i}]`)(page_2.data[i].id)(uploaded_files[i + 10].id);
  }

  // 6. Last page (page 11, only 5 files expected)
  const last_page = await api.functional.discussionBoard.member.comments.attachments.search(
    connection,
    {
      commentId: comment.id,
      body: {
        comment_id: comment.id,
        limit: 10,
        page: 11,
      },
    },
  );
  typia.assert(last_page);
  TestValidator.equals("last page length")(last_page.data.length)(5);
  for (let i = 0; i < 5; ++i) {
    TestValidator.equals(`attachment match last page [${i}]`)(last_page.data[i].id)(uploaded_files[100 + i].id);
  }

  // 7. Edge: page 12 (beyond max), should return empty array
  const empty_page = await api.functional.discussionBoard.member.comments.attachments.search(
    connection,
    {
      commentId: comment.id,
      body: {
        comment_id: comment.id,
        limit: 10,
        page: 12,
      },
    },
  );
  typia.assert(empty_page);
  TestValidator.equals("empty page")(empty_page.data.length)(0);
}

