      TestValidator.equals("thread_id")(found.thread_id ?? null)(created.thread_id ?? null);
      TestValidator.equals("post_id")(found.post_id ?? null)(created.post_id ?? null);
      TestValidator.equals("ip_address")(found.ip_address ?? null)(created.ip_address ?? null);
      TestValidator.equals("user_agent")(found.user_agent ?? null)(created.user_agent ?? null);
      TestValidator.equals("metadata_json")(found.metadata_json ?? null)(created.metadata_json ?? null);
    }
  }

  // 5. Pagination metadata is present and valid
  TestValidator.predicate("pagination exists and has expected structure")(
    pagination && typeof pagination.current === "number" && typeof pagination.limit === "number" && typeof pagination.records === "number" && typeof pagination.pages === "number"
  );

  // Should be at least as many logs as we created
  TestValidator.predicate("List contains the created activity logs")(
    data.filter((d) => createdLogs.some((c) => c.id === d.id)).length >= createdLogs.length
  );
}

