  const moderatorCreation = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      user_identifier: moderatorUserIdentifier,
      granted_at: nowTimestamp,
      revoked_at: null,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderatorCreation);

  // 2. Log recent activities as admin, once as moderator and once as member
  // a. Activity as moderator
  const moderatorActivity = await api.functional.discussionBoard.admin.activityLogs.create(connection, {
    body: {
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      actor_type: 'moderator',
      action_type: 'moderation_action',
      action_timestamp: nowTimestamp,
      topic_id: null,
      thread_id: null,
      post_id: null,
      ip_address: '127.0.0.1',
      user_agent: 'moderator-test-agent',
      metadata_json: '{"test":true}',
    } satisfies IDiscussionBoardActivityLog.ICreate,
  });
  typia.assert(moderatorActivity);

  // b. Activity as non-moderator (member)
  const memberActivity = await api.functional.discussionBoard.admin.activityLogs.create(connection, {
    body: {
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      actor_type: 'member',
      action_type: 'post_created',
      action_timestamp: nowTimestamp,
      topic_id: null,
      thread_id: null,
      post_id: null,
      ip_address: '127.0.0.2',
      user_agent: 'member-test-agent',
      metadata_json: '{"test":true}',
    } satisfies IDiscussionBoardActivityLog.ICreate,
  });
  typia.assert(memberActivity);

