  const logActorTypes = logsPage.data.map(log => log.actor_type);
  TestValidator.predicate("logs include moderator activity")(
    logActorTypes.includes('moderator')
  );
  TestValidator.predicate("logs include member activity")(
    logActorTypes.includes('member')
  );
  for (const log of logsPage.data) {
    TestValidator.predicate("actor id present")(typeof log.actor_id === 'string' && !!log.actor_id);
    TestValidator.predicate("actor type present")(typeof log.actor_type === 'string' && !!log.actor_type);
    TestValidator.predicate("action type present")(typeof log.action_type === 'string' && !!log.action_type);
    TestValidator.predicate("action timestamp present")(typeof log.action_timestamp === 'string' && !!log.action_timestamp);
  }
}

