 * 3. Update admin 1's user_identifier → NEW_A1 (unique! not A2)
 * 4. Fetch/inspect: verify admin 1's id and user_identifier is NEW_A1, but granted_at/revoked_at are unchanged
 * 5. Optionally, verify admin 2 record is untouched
 * 6. Negative: attempt to update to a duplicate user_identifier (A2) and confirm it fails
 */
export async function test_api_discussionBoard_test_update_admin_user_identifier(connection: api.IConnection) {
  // 1. Create admin 1
  const user_identifier_1 = RandomGenerator.alphaNumeric(12);
  const granted_at_1 = new Date().toISOString();
  const admin1 = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      user_identifier: user_identifier_1,
      granted_at: granted_at_1,
      revoked_at: null
    }
  });
  typia.assert(admin1);

  // 2. Create admin 2
  const user_identifier_2 = RandomGenerator.alphaNumeric(12);
  const granted_at_2 = new Date().toISOString();
  const admin2 = await api.functional.discussionBoard.admin.admins.create(connection, {
    body: {
      user_identifier: user_identifier_2,
      granted_at: granted_at_2,
      revoked_at: null
    }
  });
