  // Assign moderator role
  await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: { user_identifier: moderator_identifier, granted_at: joined_at } satisfies IDiscussionBoardModerator.ICreate,
  });

  // 2. Create a topic (category randomized)
  const topic = await api.functional.discussionBoard.admin.topics.create(connection, {
    body: {
      title: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(),
      pinned: false,
      closed: false,
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    } satisfies IDiscussionBoardTopics.ICreate,
  });
  typia.assert(topic);

  // 3. Member creates a thread in the topic
  // Assume connection is switched/emulates member after registration (framework handles)
  const thread = await api.functional.discussionBoard.member.topics.threads.create(connection, {
    topicId: topic.id,
    body: { title: RandomGenerator.paragraph()(1) } satisfies IDiscussionBoardThreads.ICreate,
  });
  typia.assert(thread);

  // 4. Attempt to delete thread as unauthorized member
  // Expect error since only moderators can use this endpoint
  await TestValidator.error("Member deletion of thread via moderator endpoint should be unauthorized")(
    async () => {
      await api.functional.discussionBoard.moderator.topics.threads.erase(connection, {
        topicId: topic.id,
        threadId: thread.id,
      });
    }
  );
}

