import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Admin advanced search for board reports: filter by reporter, status, content type, and time window.
 *
 * 1. Create multiple members as report sources.
 * 2. File several reports as those members, with diverse combinations of content_type (post/comment), status (pending/resolved), and timestamps.
 * 3. Use the admin search API to filter by:
 *    - Reporter (each reporter_id)
 *    - Status (pending vs resolved)
 *    - Content type (post vs comment)
 *    - Time window (created_from, created_to)
 * 4. For each filter/search combination:
 *    - Validate that the returned reports match the filter criteria (every record should be within search conditions, e.g., only the matching reporter, only pending status, etc).
 *    - Validate pagination shape and summary fields.
 */
export async function test_api_discussionBoard_admin_reports_test_advanced_report_search_by_admin_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create multiple members as reporting sources
  const memberData = ArrayUtil.repeat(3)(() => ({
    user_identifier: RandomGenerator.alphabets(8),
    joined_at: new Date().toISOString(),
  }) satisfies IDiscussionBoardMember.ICreate);
  const members = [] as IDiscussionBoardMember[];
  for (const data of memberData) {
    const member = await api.functional.discussionBoard.admin.members.create(connection, { body: data });
    typia.assert(member);
    members.push(member);
  }

  // 2. File different report records: combinatorial variety
  const now = new Date();
  const reportInfo: { reporter: IDiscussionBoardMember; content_type: string; status: string; created_at: string; }[] = [
    // Member 0: Post report, pending, now
    { reporter: members[0], content_type: "post", status: "pending", created_at: now.toISOString() },
    // Member 0: Comment report, resolved, now-2d
    { reporter: members[0], content_type: "comment", status: "resolved", created_at: new Date(now.getTime() - 2 * 24 * 3600 * 1000).toISOString() },
    // Member 1: Comment report, pending, now-1d
    { reporter: members[1], content_type: "comment", status: "pending", created_at: new Date(now.getTime() - 1 * 24 * 3600 * 1000).toISOString() },
    // Member 2: Post report, resolved, now-3d
    { reporter: members[2], content_type: "post", status: "resolved", created_at: new Date(now.getTime() - 3 * 24 * 3600 * 1000).toISOString() },
  ];
  const reports: IDiscussionBoardReport[] = [];
  for (const info of reportInfo) {
    const body: IDiscussionBoardReport.ICreate = {
      reporter_id: info.reporter.id,
      content_type: info.content_type,
      reported_post_id: info.content_type === "post"
        ? typia.random<string & tags.Format<"uuid">>()
        : null,
      reported_comment_id: info.content_type === "comment"
        ? typia.random<string & tags.Format<"uuid">>()
        : null,
      reason: RandomGenerator.paragraph()(1),
    };
    const report = await api.functional.discussionBoard.member.reports.create(connection, { body });
    typia.assert(report);
    // Optionally, PATCH status for resolved reports, but not available/testable with current API
    reports.push({ ...report, status: info.status, created_at: info.created_at });
  }

  // 3. Test various filters
  // Filter by reporter
  for (const member of members) {
    const result = await api.functional.discussionBoard.admin.reports.search(connection, {
      body: {
        reporter_id: member.id
      } satisfies IDiscussionBoardReport.IRequest,
    });
    typia.assert(result);
    TestValidator.predicate("all reporter match")(
      result.data.every((r) => r.reporter_id === member.id)
    );
  }
  // Filter by status
  for (const status of ["pending", "resolved"]) {
    const matchedIds = reports.filter((r) => r.status === status).map((r) => r.id);
    const result = await api.functional.discussionBoard.admin.reports.search(connection, {
      body: { status } satisfies IDiscussionBoardReport.IRequest,
