  const searchInput: IDiscussionBoardThreads.IRequest = { title: searchTerm };
  const searchResult = await api.functional.discussionBoard.topics.threads.patchByTopicid(
    connection,
    {
      topicId,
      body: searchInput,
    },
  );
  typia.assert(searchResult);

