  const memberB = await api.functional.discussionBoard.admin.members.create(connection, {
    body: {
      user_identifier: memberB_user_identifier,
      joined_at: memberB_joined_at,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  // 3. Create a topic (must specify a category ID — generate random UUID)
  const category_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
