 *
 * This test ensures that the attachment search endpoint accurately returns only the attachments
 * matching the provided filename fragment and MIME type.
 *
 * Steps:
 * 1. Create a thread and a post within it as a member (authentication handled externally).
 * 2. Upload multiple attachments with distinct filenames and MIME types to the post.
 * 3. Use the search (PATCH) endpoint with a specific filename substring and MIME type filter.
 * 4. Check that only attachments matching both criteria are included in the returned list.
 */
export async function test_api_discussionBoard_test_search_post_attachments_by_filename_and_type(connection: api.IConnection) {
  // 1. Create a threadId for use (simulating an existing thread, since thread creation is not in scope)
  //    Normally we'd create a thread via API, but use typia.random in test context.
  const threadId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Create a post within the thread as a member
  const post = await api.functional.discussionBoard.member.threads.posts.create(connection, {
    threadId,
    body: {
      discussion_board_thread_id: threadId,
      body: RandomGenerator.paragraph()(),
    },
  });
  typia.assert(post);

  // 3. Upload multiple attachments with diverse filenames and MIME types
  const filesToUpload = [
    { file_name: "dog_picture.jpg", mime_type: "image/jpeg" },
    { file_name: "cat_document.pdf", mime_type: "application/pdf" },
    { file_name: "dog_documentation.pdf", mime_type: "application/pdf" },
    { file_name: "fish_picture.jpg", mime_type: "image/jpeg" },
  ];
  const uploaded: IDiscussionBoardPostAttachment[] = [];
  for (const f of filesToUpload) {
    const attachment = await api.functional.discussionBoard.member.posts.attachments.create(connection, {
      postId: post.id,
      body: {
        discussion_board_post_id: post.id,
        uploader_member_id: post.creator_member_id,
        file_uri: RandomGenerator.url(),
        file_name: f.file_name,
        mime_type: f.mime_type,
      },
    });
    typia.assert(attachment);
    uploaded.push(attachment);
  }

  // 4. Choose a filter: find all attachments with filename containing "dog" and MIME type "application/pdf"
  const searchFilter = { file_name: "dog", mime_type: "application/pdf" };
  const searchResult = await api.functional.discussionBoard.posts.attachments.search(connection, {
    postId: post.id,
    body: {
      discussion_board_post_id: post.id,
      file_name: searchFilter.file_name,
      mime_type: searchFilter.mime_type,
    },
  });
  typia.assert(searchResult);

  // 5. Verify that every result matches BOTH filters
  for (const att of searchResult.data) {
    TestValidator.predicate("filename contains 'dog'")(att.file_name.includes("dog"));
    TestValidator.equals("mime_type matches query")(att.mime_type)("application/pdf");
    TestValidator.equals("post id matches")(att.discussion_board_post_id)(post.id);
  }

  // 6. Also verify only the expected attachments are included
  const expected = uploaded.filter(
    x => x.file_name.includes("dog") && x.mime_type === "application/pdf"
  );
  TestValidator.equals("result count matches expectation")(searchResult.data.length)(expected.length);
  for (const x of expected) {
    const found = searchResult.data.find(att => att.id === x.id);
    TestValidator.predicate("attachment present in search result")(!!found);
  }
}

