/**
 * Validate that a moderator can fetch full detail for any system notice (active, inactive, scheduled, or expired), and that a 404 error occurs for non-existent notices.
 *
 * Steps:
 * 1. Create a system notice that is currently active (is_active: true, dates cover now).
 * 2. Create a system notice that is inactive (is_active: false, no schedule required).
 * 3. Create a system notice that is scheduled for the future (is_active: true, start_at in the future).
 * 4. Create a system notice that is expired (is_active: true, start_at/end_at both in the past).
 * 5. For each of the four, fetch via the moderator endpoint and verify the detail matches all attributes.
 * 6. Attempt to fetch a clearly non-existent notice ID and verify that a not-found error occurs.
 */
export async function test_api_discussionBoard_moderator_systemNotices_test_moderator_fetch_detail_for_inactive_and_scheduled_system_notice(connection: api.IConnection) {
  // 1: Create ACTIVE notice (is_active: true, schedule covers now)
  const now = new Date();
  const past = new Date(now.getTime() - 3600 * 1000).toISOString();
  const future = new Date(now.getTime() + 3600 * 1000).toISOString();

  const activeCreate = {
    title: "Active Notice",
    body: "Visible system notice.",
    is_active: true,
    category_id: null,
    start_at: past,
    end_at: future,
  } satisfies IDiscussionBoardSystemNotice.ICreate;
  const active = await api.functional.discussionBoard.admin.systemNotices.create(connection, { body: activeCreate });
  typia.assert(active);

  // 2: Create INACTIVE notice (is_active: false, schedule irrelevant)
  const inactiveCreate = {
    title: "Inactive Notice",
    body: "Hidden system notice.",
    is_active: false,
    category_id: null,
    start_at: null,
    end_at: null,
  } satisfies IDiscussionBoardSystemNotice.ICreate;
  const inactive = await api.functional.discussionBoard.admin.systemNotices.create(connection, { body: inactiveCreate });
  typia.assert(inactive);

  // 3: Create SCHEDULED (future) notice (active, start_at in future)
  const scheduledCreate = {
    title: "Scheduled Notice",
    body: "Upcoming system notice.",
    is_active: true,
    category_id: null,
    start_at: future,
    end_at: null,
  } satisfies IDiscussionBoardSystemNotice.ICreate;
  const scheduled = await api.functional.discussionBoard.admin.systemNotices.create(connection, { body: scheduledCreate });
