  // a. Filter by notification_type = 'mention'
  const outMention = await api.functional.discussionBoard.member.notifications.search(connection, {
    body: { notification_type: 'mention', recipient_id: member.id } satisfies IDiscussionBoardNotification.IRequest
  });
