import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVersion";
import type { IPageIDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for searching, filtering, and paginating a member's own comment version history.
 *
 * This test ensures:
 * 1. A member can create a comment.
 * 2. The member can edit the comment multiple times, producing a version history.
 * 3. The member can filter/search their own comment version history (by editor, date, content).
 * 4. Pagination of version history functions correctly (page/limit/slicing).
 * 5. Filtering by editor_member_id returns only relevant versions.
 * 6. Filtering with date ranges or content_contains returns versions matching those filters.
 * 7. A different member cannot search another member's comment version history (expect an authorization error).
 *
 * Steps:
 * 1. Register MemberA and MemberB (hypothetical, must be pre-authenticated as this is not in the API set).
 * 2. MemberA creates a comment.
 * 3. MemberA edits the comment multiple times.
 * 4. Use PATCH /discussionBoard/member/comments/{commentId}/versions as MemberA to fetch versions:
 *    - No filters (should return all versions, paginated)
 *    - Filter by editor_member_id (returns only MemberA's edits)
 *    - Filter by content_contains (should find correct version)
 *    - Filter with a date range (should slice versions appropriately)
 *    - Use pagination (page/limit)
 * 5. Use PATCH as MemberB on MemberA's comment (should result in error due to access control).
 */
export async function test_api_discussionBoard_test_search_filter_and_paginate_comment_versions_for_member(connection: api.IConnection) {
  // Generate two member IDs (simulate two members)
  const memberAId = typia.random<string & tags.Format<'uuid'>>();
  const memberBId = typia.random<string & tags.Format<'uuid'>>();
  // Simulate a post ID
  const postId = typia.random<string & tags.Format<'uuid'>>();

  // 1. MemberA creates a comment
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_member_id: memberAId,
      discussion_board_post_id: postId,
      content: 'Initial comment for versioning test.'
    }
  });
  typia.assert(comment);

  // 2. MemberA edits the comment several times (create versions)
  const versions: IDiscussionBoardCommentVersion[] = [];
  for (let i = 0; i < 3; ++i) {
    const content = `Edit version ${i + 1} by MemberA ${RandomGenerator.alphaNumeric(5)}`;
    const version = await api.functional.discussionBoard.member.comments.versions.create(connection, {
      commentId: comment.id,
      body: {
        discussion_board_comment_id: comment.id,
        editor_member_id: memberAId,
        content
      }
    });
    typia.assert(version);
    versions.push(version);
  }

  // 3. Search: fetch all versions with no filter
  const allResult = await api.functional.discussionBoard.member.comments.versions.search(connection, {
    commentId: comment.id,
    body: {}
  });
  typia.assert(allResult);
  TestValidator.equals('all versions count')(allResult.data.length)(versions.length);

  // 4. Search: filter by editor_member_id
  const filteredByEditor = await api.functional.discussionBoard.member.comments.versions.search(connection, {
    commentId: comment.id,
    body: { editor_member_id: memberAId }
  });
  typia.assert(filteredByEditor);
  for (const v of filteredByEditor.data) {
    TestValidator.equals('filtered editor')(v.editor_member_id)(memberAId);
  }

  // 5. Search: filter by content_contains (use the content string from an earlier edit)
  const targetContent = versions[1].content.split(' ').slice(-1)[0]; // Grab the random token to ensure hit
  const filteredByContent = await api.functional.discussionBoard.member.comments.versions.search(connection, {
    commentId: comment.id,
    body: { content_contains: targetContent }
  });
  typia.assert(filteredByContent);
  TestValidator.predicate('content_contains filter finds at least one')(filteredByContent.data.length > 0);
  for (const v of filteredByContent.data) {
    TestValidator.predicate('content contains substring')(v.content.includes(targetContent));
  }

  // 6. Search: filter by date range
  const from = versions[0].created_at;
  const to = versions[2].created_at;
  const filteredByDate = await api.functional.discussionBoard.member.comments.versions.search(connection, {
    commentId: comment.id,
    body: { created_at_from: from, created_at_to: to }
  });
  typia.assert(filteredByDate);
  TestValidator.predicate('date-range filter returns result')(filteredByDate.data.length >= 1);

  // 7. Pagination: (simulate slicing)
  const paginated = await api.functional.discussionBoard.member.comments.versions.search(connection, {
    commentId: comment.id,
    body: {}
  });
  typia.assert(paginated);
  TestValidator.equals('pagination meta')(paginated.pagination.records)(versions.length);

  // 8. Negative: MemberB attempts to search MemberA's comment versions (simulate MemberB context)
  // (In real flow, would switch auth context here; simulate by changing editor_member_id)
  TestValidator.error('MemberB forbidden to read versions')(async () => {
    await api.functional.discussionBoard.member.comments.versions.search(connection, {
      commentId: comment.id,
      body: { editor_member_id: memberBId }
    });
  });
}

