import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Test that a discussion board member (the post owner) can update their own post content within a thread.
 *
 * This test covers the full lifecycle for a valid post update:
 * 1. Register a board member (admin creates the member)
 * 2. Create a topic as the member
 * 3. Create a thread within the topic
 * 4. Create an initial post in the thread
 * 5. Update the post's body and ensure is_edited=true, using only allowed update fields
 * 6. Validate that the returned post reflects the updates and business rules (no immutable fields changed)
 *
 * Ensures only editable fields are updated and an audit (is_edited flag, updated_at change) is applied.
 */
export async function test_api_discussionBoard_test_update_post_content_by_owner_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register new board member using admin endpoint
  const memberCreate = {
    user_identifier: RandomGenerator.alphaNumeric(16),
    joined_at: new Date().toISOString(),
  } satisfies IDiscussionBoardMember.ICreate;
  const member = await api.functional.discussionBoard.admin.members.create(connection, { body: memberCreate });
  typia.assert(member);

  // 2. Member creates a topic (simulate authentication context as that member)
  const topicCreate = {
    title: RandomGenerator.paragraph()(1, 5),
    description: RandomGenerator.paragraph()(1, 10),
    pinned: false,
    closed: false,
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
  } satisfies IDiscussionBoardTopics.ICreate;
  const topic = await api.functional.discussionBoard.member.topics.create(connection, { body: topicCreate });
  typia.assert(topic);

  // 3. Member creates a thread in the topic
  const threadCreate = {
    title: RandomGenerator.paragraph()(1, 5),
  } satisfies IDiscussionBoardThreads.ICreate;
  const thread = await api.functional.discussionBoard.member.topics.threads.create(connection, { topicId: topic.id, body: threadCreate });
  typia.assert(thread);

  // 4. Member creates a post in the thread
  const postCreate = {
    discussion_board_thread_id: thread.id,
    body: RandomGenerator.content()(1, 10),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.member.threads.posts.create(connection, { threadId: thread.id, body: postCreate });
  typia.assert(post);

  // 5. Member updates the post's body, is_edited=true
  const updatedBody = RandomGenerator.content()(2, 20);
  const postUpdate = {
    body: updatedBody,
    is_edited: true,
  } satisfies IDiscussionBoardPost.IUpdate;
  const postAfterUpdate = await api.functional.discussionBoard.member.threads.posts.update(connection, {
    threadId: thread.id,
    postId: post.id,
    body: postUpdate,
  });
  typia.assert(postAfterUpdate);

  // 6. Validate the post was updated and immutable fields not changed
  TestValidator.equals("post id")(postAfterUpdate.id)(post.id);
  TestValidator.equals("thread id")(postAfterUpdate.discussion_board_thread_id)(thread.id);
  TestValidator.equals("post owner")(postAfterUpdate.creator_member_id)(member.id);
  TestValidator.equals("body updated")(postAfterUpdate.body)(updatedBody);
  TestValidator.equals("is_edited flag")(postAfterUpdate.is_edited)(true);
  TestValidator.notEquals("updated_at changed")(postAfterUpdate.updated_at)(post.updated_at);
  TestValidator.equals("created_at unchanged")(postAfterUpdate.created_at)(post.created_at);
  TestValidator.equals("deleted_at unchanged")(postAfterUpdate.deleted_at ?? null)(post.deleted_at ?? null);
}

