import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardSubscription } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSubscription";

/**
 * Validate access control on updating another user's discussion board subscription.
 *
 * This test verifies that users cannot update a subscription unless they are the owner or have admin rights.
 *
 * Steps:
 * 1. As an admin, create two distinct members (the legitimate owner and a second, unrelated user).
 * 2. As an admin, create a subscription record for the first member (owner) targeting some thread/topic.
 * 3. Simulate 'login' as the second member (not admin, not owner).
 * 4. Attempt to update the first member's subscription as the second member, changing notification_method and/or is_active fields.
 * 5. Assert that the API denies this action (permission error/forbidden).
 */
export async function test_api_discussionBoard_test_update_subscription_with_unauthorized_user(
  connection: api.IConnection,
) {
  // 1. Create two members as admin
  const memberOwner = await api.functional.discussionBoard.admin.members.create(connection, {
    body: {
      user_identifier: RandomGenerator.alphaNumeric(16),
      joined_at: new Date().toISOString(),
    },
  });
  typia.assert(memberOwner);

  const memberAttacker = await api.functional.discussionBoard.admin.members.create(connection, {
    body: {
      user_identifier: RandomGenerator.alphaNumeric(16),
      joined_at: new Date().toISOString(),
    },
  });
  typia.assert(memberAttacker);

  // 2. Create a subscription for the owner
  const targetId = typia.random<string & tags.Format<"uuid">>();
  const subscription = await api.functional.discussionBoard.member.subscriptions.create(connection, {
    body: {
      subscriber_id: memberOwner.id,
      target_type: "topic",
      target_id: targetId,
      notification_method: "email",
      is_active: true,
    },
  });
  typia.assert(subscription);

