 * Test forbidden access to comment attachment detail for unauthorized roles.
 * 
 * This test validates that only authorized users (moderators or the resource owner) may access attachment metadata for a comment, and other users (non-owners, other members, or guests) must be denied. We construct a canonical scenario where an authentic member (the owner) uploads an attachment to their comment, then try to retrieve attachment detail as an unrelated member (to simulate a forbidden/unauthorized access attempt).
 *
 * Steps:
 * 1. Register the legitimate board member (owner A)
 * 2. Owner A creates a comment (on an arbitrary post)
 * 3. Owner A uploads an attachment to the comment
 * 4. Register another member (member B), who is NOT the owner and is not a moderator
 * 5. As member B, attempt to get the attachment metadata detail through the moderator endpoint, expecting forbidden or error
 * 6. Additionally, validate the same forbidden behavior for a guest (no authentication)
 */
export async function test_api_discussionBoard_test_get_comment_attachment_detail_forbidden_for_unauthorized(
  connection: api.IConnection,
) {
  // 1. Register owner member (A)
  const ownerUserIdentifier = RandomGenerator.alphaNumeric(16);
  const ownerMember = await api.functional.discussionBoard.admin.members.create(connection, {
    body: {
      user_identifier: ownerUserIdentifier,
      joined_at: new Date().toISOString(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(ownerMember);

  // 2. Owner creates a comment
  const postId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_member_id: ownerMember.id,
      discussion_board_post_id: postId,
      content: RandomGenerator.paragraph()(2),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 3. Owner uploads an attachment to the comment
  const attachment = await api.functional.discussionBoard.member.comments.attachments.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      uploader_member_id: ownerMember.id,
      file_name: `file_${RandomGenerator.alphaNumeric(8)}.png`,
      file_url: `https://cdn.test/${RandomGenerator.alphaNumeric(8)}.png`,
      mime_type: "image/png",
    } satisfies IDiscussionBoardCommentAttachment.ICreate,
  });
  typia.assert(attachment);

  // 4. Register another member (B, unauthorized)
  const unauthorizedUserIdentifier = RandomGenerator.alphaNumeric(16);
  const unauthorizedMember = await api.functional.discussionBoard.admin.members.create(connection, {
    body: {
      user_identifier: unauthorizedUserIdentifier,
      joined_at: new Date().toISOString(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(unauthorizedMember);

  // --- Here we would switch context to the unauthorized member (B)
