  // 5. Attempt forbidden attachment detail access as non-owner/non-moderator
  await TestValidator.error("unauthorized member must be forbidden")(() =>
    api.functional.discussionBoard.moderator.comments.attachments.at(connection, {
      commentId: comment.id,
      attachmentId: attachment.id,
    })
