  // 2. Create a report for a post (randomly generated post UUID, valid reporter UUID)
  const reporterId = typia.random<string & tags.Format<"uuid">>();
  const reportedPostId = typia.random<string & tags.Format<"uuid">>();
  const report = await api.functional.discussionBoard.admin.reports.create(connection, {
    body: {
      reporter_id: reporterId,
      content_type: "post",
      reported_post_id: reportedPostId,
      reported_comment_id: null,
      reason: "Spam or irrelevant content",
    },
  });
  typia.assert(report);

  // 3. Create a moderation action (action_type: 'delete', action_details sample evidence, linked actor/report)
  const moderationAction = await api.functional.discussionBoard.admin.moderationActions.create(connection, {
    body: {
      actor_moderator_id: moderatorAssignment.id,
      actor_admin_id: null,
      post_id: report.reported_post_id ?? null,
      comment_id: null,
      report_id: report.id,
      action_type: "delete",
      action_details: "Content removed for repeated spam. See evidence: screenshot123.png",
    },
  });
  typia.assert(moderationAction);

  // 4. Assert key fields are accurate
  TestValidator.equals("moderation action actor moderator id")(moderationAction.actor_moderator_id)(moderatorAssignment.id);
  TestValidator.equals("moderation action report id")(moderationAction.report_id)(report.id);
  TestValidator.equals("moderation action action_type")(moderationAction.action_type)("delete");
  TestValidator.equals("moderation action action_details")(moderationAction.action_details)("Content removed for repeated spam. See evidence: screenshot123.png");
  TestValidator.equals("moderation action post_id")(moderationAction.post_id)(report.reported_post_id);
  TestValidator.equals("moderation action comment_id")(moderationAction.comment_id)(null);
  TestValidator.predicate("created_at is present")(typeof moderationAction.created_at === "string" && moderationAction.created_at.length > 0);
  TestValidator.predicate("id is uuid")(typeof moderationAction.id === "string" && moderationAction.id.length > 0);
}

