import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IDiscussionBoardCategoryModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategoryModerator";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";

/**
 * Test that updating a moderator assignment to a moderator/category pair that already exists fails (unique constraint).
 *
 * 1. Create a new discussion category
 * 2. Create moderator A
 * 3. Create moderator B
 * 4. Assign moderator A to the category (assignment1)
 * 5. Assign moderator B to the same category (assignment2)
 * 6. Attempt to update assignment2 to point to moderator A (who is already assigned).
 * 7. Validate that the API returns a unique constraint error (typically 409)
 * 8. Confirm that no duplicate assignment exists for the moderator/category pair
 */
export async function test_api_discussionBoard_test_update_category_moderator_assignment_duplicate_constraint_violation(connection: api.IConnection) {
  // 1. Create a new discussion category
  const category = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: `카테고리_${RandomGenerator.alphabets(8)}`,
      is_active: true,
      description: RandomGenerator.paragraph()(),
      parent_id: null,
    },
  });
  typia.assert(category);

  // 2. Create moderator A
  const moderatorA = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      user_identifier: `modA_${RandomGenerator.alphaNumeric(10)}`,
      granted_at: new Date().toISOString(),
      revoked_at: null,
    },
  });
  typia.assert(moderatorA);

  // 3. Create moderator B
  const moderatorB = await api.functional.discussionBoard.admin.moderators.create(connection, {
    body: {
      user_identifier: `modB_${RandomGenerator.alphaNumeric(10)}`,
      granted_at: new Date().toISOString(),
      revoked_at: null,
    },
  });
  typia.assert(moderatorB);

  // 4. Assign moderator A to category
  const assignmentA = await api.functional.discussionBoard.admin.categories.categoryModerators.create(connection, {
    categoryId: category.id,
    body: {
      category_id: category.id,
      moderator_id: moderatorA.id
    },
  });
  typia.assert(assignmentA);

  // 5. Assign moderator B to category
  const assignmentB = await api.functional.discussionBoard.admin.categories.categoryModerators.create(connection, {
    categoryId: category.id,
    body: {
      category_id: category.id,
      moderator_id: moderatorB.id
    },
  });
  typia.assert(assignmentB);

  // 6. Attempt to update assignmentB to point to moderatorA (who is already assigned for the same category)
  await TestValidator.error("Unique constraint violation when updating category moderator assignment")(async () => {
    await api.functional.discussionBoard.admin.categories.categoryModerators.update(connection, {
      categoryId: category.id,
      categoryModeratorId: assignmentB.id,
      body: {
        moderator_id: moderatorA.id,
      },
    });
  });
}

