import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";

/**
 * 테스트 목적: 스레드 내 게시물 검색 API의 페이지네이션 기능을 검증한다.
 *
 * 1. 새 토픽을 생성한다.
 * 2. 해당 토픽에 속한 스레드를 생성한다.
 * 3. 테스트에 필요한 최소 15개(페이지 limit보다 많은 수)의 게시물을 생성한다.
 * 4. 게시물 검색 API를 limit=10, page=1로 조회한다.  
 *    - 결과가 10개임을 확인하고, 전체 게시물 개수 및 페이지 수가 올바른지 검사한다.
 *    - 데이터의 내림차순/오름차순(기본 정렬 기준: 최신순 등) 정렬 상태도 검증한다.
 * 5. 같은 조건으로 page=2로 조회한다.
 *    - 나머지(5개) 게시물 반환 확인 및 페이지네이션 정보가 올바른지 점검한다.
 * 6. 중복/누락 없이 전체 데이터가 검색되는지 확인한다.
 */
export async function test_api_discussionBoard_test_search_posts_in_thread_with_pagination(connection: api.IConnection) {
  // 1. 새 토픽 생성
  const topic = await api.functional.discussionBoard.member.topics.create(connection, {
    body: {
      title: RandomGenerator.alphabets(10),
      description: RandomGenerator.paragraph()(),
      pinned: false,
      closed: false,
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
    }
  });
  typia.assert(topic);

  // 2. 새 스레드 생성
  const thread = await api.functional.discussionBoard.member.topics.threads.create(connection, {
    topicId: topic.id,
    body: {
      title: RandomGenerator.alphabets(12),
    },
  });
  typia.assert(thread);

  // 3. 게시물 15개 생성
  const postBodies: string[] = ArrayUtil.repeat(15)(() => RandomGenerator.paragraph()());
  const postIds: string[] = [];

  for (const body of postBodies) {
    const post = await api.functional.discussionBoard.member.threads.posts.create(connection, {
      threadId: thread.id,
      body: {
        discussion_board_thread_id: thread.id,
        body: body,
      }
    });
    typia.assert(post);
    postIds.push(post.id);
  }

  // 4. 첫 페이지 (limit=10, page=1)로 검색
  const page1 = await api.functional.discussionBoard.member.threads.posts.search(connection, {
    threadId: thread.id,
    body: {
      threadId: thread.id,
      pagination: {
        page: 1,
        limit: 10,
      },
    },
  });
  typia.assert(page1);
  TestValidator.equals('첫 페이지 게시글 수')(page1.data.length)(10);
  TestValidator.equals('페이지네이션 현재 페이지')(page1.pagination.current)(1);
  TestValidator.equals('페이지네이션 페이지당 수')(page1.pagination.limit)(10);
  TestValidator.equals('총 게시글 수')(page1.pagination.records)(15);
  TestValidator.equals('총 페이지 수')(page1.pagination.pages)(2);

  // 정렬(최신 생성순, created_at 역순 등) 상태 확인: 기본은 생성 시점 최신순으로 가정
  const createdAtsPage1 = page1.data.map((p) => p.created_at);
  for (let i = 1; i < createdAtsPage1.length; ++i) {
    // created_at 내림차순(최신순)
    TestValidator.predicate('created_at 최신순')(createdAtsPage1[i-1] >= createdAtsPage1[i]);
  }

  // 5. 두 번째 페이지 (limit=10, page=2)로 검색
  const page2 = await api.functional.discussionBoard.member.threads.posts.search(connection, {
    threadId: thread.id,
    body: {
      threadId: thread.id,
      pagination: {
        page: 2,
        limit: 10,
      },
    },
  });
  typia.assert(page2);
  TestValidator.equals('두 번째 페이지 게시글 수')(page2.data.length)(5);
  TestValidator.equals('페이지네이션 현재 페이지')(page2.pagination.current)(2);

  // 6. 전체 데이터 카운트와 실제 반환을 비교하여 중복 및 누락 없는지 확인
  const allPostIds = [...page1.data, ...page2.data].map((p) => p.id);
  TestValidator.equals('전체 게시글 중복/누락 없음')(new Set(allPostIds).size)(15);
  for (const id of postIds) {
    TestValidator.predicate('생성한 게시글 반환 포함')(allPostIds.includes(id));
  }
}

