 *
 * Steps involved:
 * 1. Generate a valid report payload as an admin, reporting either a post or a comment (randomly chosen).
 * 2. Call the /discussionBoard/admin/reports POST endpoint with the admin credentials and the prepared payload.
 * 3. Validate that the response contains a new report entity with metadata, admin's reporter_id, appropriate content_type, set status (should be 'pending' initially), creation timestamp, and no resolved_at since it's a fresh report.
 * 4. Optionally, check that irrelevant fields (e.g., reported_comment_id when content_type is 'post') are null or undefined as per schema.
 */
export async function test_api_discussionBoard_test_create_report_as_admin_successful(connection: api.IConnection) {
  // 1. Prepare admin context and valid moderation report payload
  // (Assume connection context has admin privileges. Generate both post and comment scenarios)

  const reporter_id: string = typia.random<string & tags.Format<"uuid">>();
  const reportType = Math.random() < 0.5 ? "post" : "comment";

  const payload: IDiscussionBoardReport.ICreate = reportType === "post"
    ? {
        reporter_id,
        content_type: "post",
        reported_post_id: typia.random<string & tags.Format<"uuid">>(),
        reported_comment_id: null,
        reason: "Violation of community guidelines (test)"
      }
    : {
        reporter_id,
        content_type: "comment",
        reported_post_id: null,
        reported_comment_id: typia.random<string & tags.Format<"uuid">>(),
        reason: "Inappropriate comment content (test)"
      };

