  const output = await api.functional.discussionBoard.admin.reports.create(connection, {
    body: payload
  });
  typia.assert(output);

  // 3. Validate core metadata and field assignment
  TestValidator.equals("reporter_id matches")(output.reporter_id)(reporter_id);
  TestValidator.equals("content_type matches")(output.content_type)(payload.content_type);
  TestValidator.equals("status should be pending")(output.status)("pending");
  TestValidator.predicate("created_at present and is a valid date")(
    typeof output.created_at === "string" && !isNaN(Date.parse(output.created_at))
  );
  TestValidator.equals("resolved_at should be null for new report")(output.resolved_at)(null);

  // 4. For the selected report type, check only the correct ID field is populated
  if (reportType === "post") {
    TestValidator.equals("reported_post_id set")(output.reported_post_id)(payload.reported_post_id);
    TestValidator.equals("reported_comment_id is null or undefined")(output.reported_comment_id)(null);
  } else {
    TestValidator.equals("reported_comment_id set")(output.reported_comment_id)(payload.reported_comment_id);
    TestValidator.equals("reported_post_id is null or undefined")(output.reported_post_id)(null);
  }
}

