import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced activity log search with role and date filters for moderator.
 *
 * - Precondition: Insert several activity logs (as setup, performed by both "member" and "moderator" roles, with action_timestamps across a range of dates)
 * - As a moderator, search for logs where actor_type is 'member' and date range is [T1, T2], verify:
 *    1. All logs are by 'member' within the specified period.
 *    2. Page/limit work (pagination yields correct number/structure, respects limits)
 *    3. Expected logs from setup are present in results.
 * - As a moderator, search for logs with actor_type 'moderator' and different date range, validate as above.
 * - Try searching with invalid date format and expect an error.
 * - Try searching as an unauthenticated user (connection with empty/invalid Authorization header), expect access denied error.
 * - Try with malformed request (e.g., page negative or limit excessively large), expect error.
 * - Try with an actor_type that is nonsense, expect valid empty response (no log).
 */
export async function test_api_discussionBoard_test_search_activity_logs_with_role_and_date_filters(
  connection: api.IConnection,
) {
  // Step 1: Create baseline audit log entries for setup, with at least 2 roles and varying timestamps.
  const memberActorId = typia.random<string & tags.Format<"uuid">>();
  const moderatorActorId = typia.random<string & tags.Format<"uuid">>();
  const log1 = await api.functional.discussionBoard.moderator.activityLogs.create(connection, { body: { actor_id: memberActorId, actor_type: 'member', action_type: 'view_post', action_timestamp: '2025-07-10T10:00:00.000Z' } satisfies IDiscussionBoardActivityLog.ICreate });
  const log2 = await api.functional.discussionBoard.moderator.activityLogs.create(connection, { body: { actor_id: moderatorActorId, actor_type: 'moderator', action_type: 'moderation_action', action_timestamp: '2025-07-15T12:00:00.000Z' } satisfies IDiscussionBoardActivityLog.ICreate });
  const log3 = await api.functional.discussionBoard.moderator.activityLogs.create(connection, { body: { actor_id: memberActorId, actor_type: 'member', action_type: 'comment_created', action_timestamp: '2025-07-18T15:00:00.000Z' } satisfies IDiscussionBoardActivityLog.ICreate });
  typia.assert(log1); typia.assert(log2); typia.assert(log3);

  // Step 2: Search for 'member' logs between '2025-07-09' and '2025-07-19' (should return log1 and log3 only)
  const memberSearch = await api.functional.discussionBoard.moderator.activityLogs.search(connection, {
    body: { actor_type: 'member', action_timestamp_from: '2025-07-09T00:00:00.000Z', action_timestamp_to: '2025-07-19T23:59:59.999Z', page: 1, limit: 10 } satisfies IDiscussionBoardActivityLog.IRequest
  });
  typia.assert(memberSearch);
  for (const log of memberSearch.data) {
    TestValidator.equals('actor_type is member')(log.actor_type)('member');
    TestValidator.predicate('timestamp in range')(
      log.action_timestamp >= '2025-07-09T00:00:00.000Z' &&
      log.action_timestamp <= '2025-07-19T23:59:59.999Z'
    );
  }
  TestValidator.predicate('contains setup logs')(
    memberSearch.data.some(x => x.id === log1.id) &&
    memberSearch.data.some(x => x.id === log3.id)
  );

  // Step 3: Pagination test (limit=1 should return only 1 record per page)
  const paged = await api.functional.discussionBoard.moderator.activityLogs.search(connection, {
    body: { actor_type: 'member', action_timestamp_from: '2025-07-09T00:00:00.000Z', action_timestamp_to: '2025-07-19T23:59:59.999Z', page: 1, limit: 1 } satisfies IDiscussionBoardActivityLog.IRequest
  });
  typia.assert(paged);
  TestValidator.equals('limit respected')(paged.data.length)(1);
  TestValidator.equals('pagination info')(paged.pagination.limit)(1);

  // Step 4: Search 'moderator' logs for just 2025-07-15
  const modSearch = await api.functional.discussionBoard.moderator.activityLogs.search(connection, {
    body: { actor_type: 'moderator', action_timestamp_from: '2025-07-15T00:00:00.000Z', action_timestamp_to: '2025-07-15T23:59:59.999Z', page: 1, limit: 10 } satisfies IDiscussionBoardActivityLog.IRequest
  });
  typia.assert(modSearch);
  for (const log of modSearch.data) {
    TestValidator.equals('actor_type is moderator')(log.actor_type)('moderator');
    TestValidator.predicate('timestamp is 2025-07-15')(
      log.action_timestamp >= '2025-07-15T00:00:00.000Z' &&
      log.action_timestamp <= '2025-07-15T23:59:59.999Z'
    );
  }
  TestValidator.predicate('contains log2')(modSearch.data.some(x => x.id === log2.id));

  // Step 5: Invalid date format should trigger error
  await TestValidator.error('invalid date format')(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(connection, {
      body: { actor_type: 'member', action_timestamp_from: '2025-07-009T00:00:00', page: 1, limit: 10 } satisfies IDiscussionBoardActivityLog.IRequest
    })
  );

  // Step 6: Non-privileged/unauthorized user search attempt should fail (simulate by removing any authorization header)
  const anonConnection = { ...connection, headers: { ...connection.headers, Authorization: '' } };
  await TestValidator.error('unauthorized search should fail')(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(anonConnection, {
      body: { actor_type: 'member', page: 1, limit: 10 } satisfies IDiscussionBoardActivityLog.IRequest
    })
  );

  // Step 7: Malformed filter: negative page or excessive limit
  await TestValidator.error('negative page')(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(connection, {
      body: { actor_type: 'member', page: -1, limit: 10 } satisfies IDiscussionBoardActivityLog.IRequest
    })
  );
  await TestValidator.error('too large limit')(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(connection, {
      body: { actor_type: 'member', page: 1, limit: 1000000 } satisfies IDiscussionBoardActivityLog.IRequest
    })
  );

  // Step 8: actor_type nonsense value yields empty result (should not error, just no logs)
  const nonsenseRes = await api.functional.discussionBoard.moderator.activityLogs.search(connection, {
    body: { actor_type: 'NOT_A_REAL_ROLE', page: 1, limit: 10 } satisfies IDiscussionBoardActivityLog.IRequest
  });
  typia.assert(nonsenseRes);
  TestValidator.equals('no logs for nonsense actor_type')(nonsenseRes.data.length)(0);
}

