  const modSearch =
    await api.functional.discussionBoard.moderator.activityLogs.search(
      connection,
      {
        body: {
          actor_type: "moderator",
          action_timestamp_from: "2025-07-15T00:00:00.000Z",
          action_timestamp_to: "2025-07-15T23:59:59.999Z",
          page: 1,
          limit: 10,
