import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * Verify the visibility filtering of system notices for guest users (not authenticated).
 *
 * This test will ensure that guests (non-logged-in users) can only see system notices that are active AND their schedule is currently valid (current time is within start_at/end_at range, or they are non-scheduled but active). Inactive, expired, and future-scheduled (not yet started) notices must NOT be returned to guests.
 *
 * Detailed Steps:
 * 1. Create various types of system notices via admin:
 *    - Active, always visible (no schedule)
 *    - Active, currently scheduled (start_at <= now <= end_at)
 *    - Active, scheduled to start in future (start_at > now)
 *    - Active, already expired (end_at < now)
 *    - Inactive, always (regardless of schedule)
 * 2. Access the GET /discussionBoard/moderator/systemNotices endpoint WITHOUT authentication (as guest)
 * 3. Assert that only those notices which are both active and currently within (if scheduled) their start_at/end_at windows show up
 * 4. Confirm that scheduled-in-future, already expired, and inactive notices are NOT returned
 * 5. Optionally, check that returned objects' content matches those created in step 1 (title/body validation)
 */
export async function test_api_discussionBoard_test_list_system_notices_for_guest_visibility_scope(
  connection: api.IConnection,
) {
  // 1. Define 'now' reference for scheduling
  const now = new Date();

  // 2. Admin creates: active/always, active/current, active/future, active/expired, inactive
  const notice_active_always = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "Active, always visible",
        body: "This notice should always be shown while active.",
        is_active: true,
        category_id: null,
        start_at: null,
        end_at: null,
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(notice_active_always);

  const notice_active_current = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "Active, currently scheduled",
        body: "Visible to guests: start_at <= now <= end_at.",
        is_active: true,
        category_id: null,
        start_at: new Date(now.getTime() - 60 * 1000).toISOString(), // started 1 min ago
        end_at: new Date(now.getTime() + 60 * 60 * 1000).toISOString(), // ends in 1 hour
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(notice_active_current);

  const notice_active_future = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "Active, scheduled for future",
        body: "Should NOT be visible to guests yet.",
        is_active: true,
        category_id: null,
        start_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(), // starts in 1 day
        end_at: null,
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(notice_active_future);

  const notice_active_expired = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "Active, expired",
        body: "Was once visible, but now expired.",
        is_active: true,
        category_id: null,
        start_at: new Date(now.getTime() - 24 * 60 * 60 * 1000).toISOString(), // started 1 day ago
        end_at: new Date(now.getTime() - 60 * 1000).toISOString(), // ended 1 min ago
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(notice_active_expired);

  const notice_inactive = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "Inactive, always",
        body: "Inactive notices must never be visible to guests.",
        is_active: false,
        category_id: null,
        start_at: null,
        end_at: null,
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(notice_inactive);

  // 3. As guest: list system notices
  const output = await api.functional.discussionBoard.moderator.systemNotices.index(connection);
  typia.assert(output);

  // 4. Only valid notices must appear
  const ids_should_be_visible = [
    notice_active_always.id,
    notice_active_current.id,
  ];

  const visible_ids = output.data.map((n) => n.id);

  // Ensure ALL expected are present
  for (const expected_id of ids_should_be_visible) {
    TestValidator.predicate(`notice ${expected_id} must be visible as guest`)(
      visible_ids.includes(expected_id)
    );
  }
  // Ensure NOT expected are absent
  for (const not_expected of [
    notice_active_future.id,
    notice_active_expired.id,
    notice_inactive.id,
  ]) {
    TestValidator.predicate(`notice ${not_expected} must NOT be visible as guest`)(
      !visible_ids.includes(not_expected)
    );
  }

  // Optionally: check title/body content match for visible notices
  const by_id = Object.fromEntries(output.data.map((n) => [n.id, n]));
  TestValidator.equals("title matches")(
    by_id[notice_active_always.id]?.title
  )("Active, always visible");
  TestValidator.equals("body matches")(
    by_id[notice_active_always.id]?.body
  )("This notice should always be shown while active.");

  TestValidator.equals("title matches")(
    by_id[notice_active_current.id]?.title
  )("Active, currently scheduled");
  TestValidator.equals("body matches")(
    by_id[notice_active_current.id]?.body
  )("Visible to guests: start_at <= now <= end_at.");
}

