import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 시스템 공지사항 목록을 모더레이터 권한으로 조회할 수 있음을 검증합니다.
 *
 * 이 테스트는 다음 사항을 검증합니다:
 * 1. 활성(공개), 비활성(숨김), 미래 예약(스케줄), 기간 만료(과거) 등 다양한 상태의 공지사항이 모두 조회 대상으로 포함되는지 검증합니다.
 * 2. 각 상태별 공지사항을 직접 생성한 후, 모더레이터 권한으로 목록을 조회합니다.
 * 3. 각 공지사항은 반드시 category_id, title, body, is_active, start_at, end_at, created_at, updated_at 등 메타데이터를 모두 포함해야 합니다.
 * 4. 반환된 결과의 pagination 정보(current, limit, records, pages)도 올바른지 확인합니다.
 * 5. 페이징 size가 맞춰져 있는지, 여러 종류의 공지들이 빠짐없이 반환되는지 확인하고, 각 공지의 메타 정보가 누락 없이 제공되는지 검증합니다.
 */
export async function test_api_discussionBoard_test_list_system_notices_as_moderator_with_access_to_all_visibility_statuses(
  connection: api.IConnection,
) {
  // 1. 다양한 상태의 공지사항을 관리자 API로 생성 (활성, 비활성, 예약, 만료)
  const now = new Date();
  const farFuture = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // +7일 후
  const farPast = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000); // -7일 전

  // 활성 공지
  const noticeActive = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "[ACTIVE] [32mActive Notice[0m",
        body: "This is an active notice",
        is_active: true,
        start_at: null,
        end_at: null,
        category_id: null,
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(noticeActive);

  // 비활성 공지
  const noticeInactive = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "[INACTIVE] Inactive Notice",
        body: "This is an inactive notice",
        is_active: false,
        start_at: null,
        end_at: null,
        category_id: null,
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(noticeInactive);

  // 미래 예약 공지
  const noticeScheduled = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "[SCHEDULED] Future Notice",
        body: "This is a notice scheduled for the future",
        is_active: true,
        start_at: farFuture.toISOString(),
        end_at: null,
        category_id: null,
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(noticeScheduled);

  // 기간 만료 공지
  const noticeExpired = await api.functional.discussionBoard.admin.systemNotices.create(
    connection,
    {
      body: {
        title: "[EXPIRED] Expired Notice",
        body: "This notice expired previously",
        is_active: true,
        start_at: farPast.toISOString(),
        end_at: now.toISOString(),
        category_id: null,
      } satisfies IDiscussionBoardSystemNotice.ICreate,
    },
  );
  typia.assert(noticeExpired);

  // 2. 모더레이터 권한으로 전체 공지사항 목록을 조회
  const list = await api.functional.discussionBoard.moderator.systemNotices.index(
    connection,
  );
  typia.assert(list);

  // 3. pagination 메타 정보 검증
  TestValidator.predicate("pagination info 유효성")(
    list.pagination &&
      typeof list.pagination.current === "number" &&
      typeof list.pagination.limit === "number" &&
      typeof list.pagination.records === "number" &&
      typeof list.pagination.pages === "number",
  );

  // 4. 결과 데이터 최소 개수(생성한 4개)가 모두 포함되어 있는지 확인
  const createdIds = [noticeActive.id, noticeInactive.id, noticeScheduled.id, noticeExpired.id];
  const foundIds = list.data.map(n => n.id);
  createdIds.forEach(id => {
    TestValidator.predicate(`공지 ID 포함 여부: ${id}`)(foundIds.includes(id));
  });

  // 5. 각 공지의 메타 필드가 올바르게 포함되어 있는지 체크
  list.data.forEach(notice => {
    TestValidator.predicate("id exists")(typeof notice.id === "string" && !!notice.id);
    TestValidator.predicate("title exists")(typeof notice.title === "string" && !!notice.title);
    TestValidator.predicate("body exists")(typeof notice.body === "string");
    TestValidator.predicate("is_active exists")(typeof notice.is_active === "boolean");
    TestValidator.predicate("created_at exists")(typeof notice.created_at === "string");
    TestValidator.predicate("updated_at exists")(typeof notice.updated_at === "string");
    // Nullable optional fields
