import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCategory";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * Validate category-based filtering and pagination for system notice listing (moderator API).
 *
 * Business context:
 * The discussion board supports system notices that may be global (not category-limited) or assigned to a specific category. Moderators need to see both global and category-specific notices, and UI/UX needs to confirm list/pagination and filtering work.
 *
 * Steps:
 * 1. Admin creates a board category.
 * 2. Admin creates a system notice linked to that category (category-specific notice).
 * 3. Admin creates several global notices (category_id null).
 * 4. (Optional) Admin creates additional notices to ensure there are enough to test pagination (limit/page behavior).
 * 5. Moderator calls GET /discussionBoard/moderator/systemNotices to list notices (covering both unfiltered and filtered scenarios if query params supported).
 * 6. Verify response contains both the category-specific and global notices (at minimum). Ensure notices have expected fields and correct category linkage.
 * 7. If pagination is triggered, confirm paging info (total records, limit, pages, correct number of results), and navigation across pages works properly if query parameters can be supplied (if not, skip multi-page checks).
 */
export async function test_api_discussionBoard_test_list_system_notices_pagination_and_filtering_by_category_id(connection: api.IConnection) {
  // 1. Create a board category (admin)
  const category = await api.functional.discussionBoard.admin.categories.create(connection, {
    body: {
      name: `Category_${RandomGenerator.alphaNumeric(6)}`,
      description: RandomGenerator.paragraph()(),
      is_active: true
    } satisfies IDiscussionBoardCategory.ICreate,
  });
  typia.assert(category);

  // 2. Create one category-specific notice (with category_id)
  const noticeByCategory = await api.functional.discussionBoard.admin.systemNotices.create(connection, {
    body: {
      category_id: category.id,
      title: `Cat-Notice_${RandomGenerator.alphaNumeric(5)}`,
      body: RandomGenerator.paragraph()(),
      is_active: true
    } satisfies IDiscussionBoardSystemNotice.ICreate,
  });
  typia.assert(noticeByCategory);

  // 3. Create several global notices (category_id = null)
  const globalNotices: IDiscussionBoardSystemNotice[] = [];
  for (let i = 0; i < 7; ++i) {
    // 7 for stressing pagination (assuming default limit low enough)
    const notice = await api.functional.discussionBoard.admin.systemNotices.create(connection, {
      body: {
        category_id: null,
        title: `GlobalNotice_${i}_${RandomGenerator.alphaNumeric(4)}`,
        body: RandomGenerator.paragraph()(),
        is_active: true
      } satisfies IDiscussionBoardSystemNotice.ICreate
    });
    typia.assert(notice);
    globalNotices.push(notice);
  }

  // 4. Moderator queries /discussionBoard/moderator/systemNotices
  const response = await api.functional.discussionBoard.moderator.systemNotices.index(connection);
  typia.assert(response);

  // 5. Validation: at least the created notices exist, correct fields, category linkage
  // -- Contains the category-specific notice
  TestValidator.predicate("category-specific notice included")(
    response.data.some(n => n.id === noticeByCategory.id && n.category_id === category.id)
  );
  // -- Contains global notices
  for (const notice of globalNotices) {
    TestValidator.predicate(`global notice ${notice.title} included`)(
      response.data.some(n => n.id === notice.id && n.category_id === null)
    );
  }
  // -- Category-specific notice must have non-null category_id
  TestValidator.equals("category_id linkage")(noticeByCategory.category_id)(category.id);
  // -- Global notices must have null category_id
  for (const notice of globalNotices) {
    TestValidator.equals("global notice has null category_id")(notice.category_id)(null);
  }
  // 6. Pagination info: data length <= limit, total records >= created
  TestValidator.predicate("records count")(
    response.pagination.records >= 1 + globalNotices.length
  );
  TestValidator.predicate("page size <= limit")(
    response.data.length <= response.pagination.limit
  );
  TestValidator.predicate("page count > 0")(
    response.pagination.pages > 0
  );
}

