import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentVersion";
import type { IPageIDiscussionBoardCommentVersion } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardCommentVersion";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and pagination of a comment's version history by a moderator.
 *
 * Ensures that:
 * 1. A member creates a comment under a post.
 * 2. Multiple versions are created for that comment: both by the member (original author) and the moderator (acting as editor).
 * 3. Moderator executes advanced search:
 *    - Filter by editor_member_id (should only return moderator's edits)
 *    - Filter by date/time range (created_at_from/to)
 *    - Filter by content (content_contains)
 *    - Use pagination (test at least the structure for paging)
 * 4. Verify that results returned only match search criteria.
 * 5. Test access control (moderator can perform), and error case for invalid commentId (should return error, validated via TestValidator.error()).
 */
export async function test_api_discussionBoard_test_moderator_advanced_search_on_comment_versions(
  connection: api.IConnection,
) {
  // 1. MEMBER creates a comment for a post
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const postId: string = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(connection, {
    body: {
      discussion_board_member_id: memberId,
      discussion_board_post_id: postId,
      content: "Initial member comment content."
    }
  });
  typia.assert(comment);

  // 2. First version by member (simulate edit)
  const memberEditContent = "Member edit 1 content.";
  const memberEdit = await api.functional.discussionBoard.moderator.comments.versions.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      editor_member_id: memberId,
      content: memberEditContent
    }
  });
  typia.assert(memberEdit);

  // 3. Moderator creates two edits/versions
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const modEditContent1 = "Moderator edit version 1";
  const modEdit1 = await api.functional.discussionBoard.moderator.comments.versions.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      editor_member_id: moderatorId,
      content: modEditContent1
    }
  });
  typia.assert(modEdit1);

  // Introduce small delay and create a second moderator version (to test date filters)
  await new Promise(res => setTimeout(res, 50));
  const modEditContent2 = "Moderator edit version 2";
  const modEdit2 = await api.functional.discussionBoard.moderator.comments.versions.create(connection, {
    commentId: comment.id,
    body: {
      discussion_board_comment_id: comment.id,
      editor_member_id: moderatorId,
      content: modEditContent2
    }
  });
  typia.assert(modEdit2);

  // 4. Search comment versions filtered by moderator as editor
  const searchResponse = await api.functional.discussionBoard.moderator.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      editor_member_id: moderatorId
    }
  });
  typia.assert(searchResponse);
  const moderatorVersionIds = [modEdit1.id, modEdit2.id];
  TestValidator.equals("only moderator versions present")(
    new Set(searchResponse.data.map(v => v.id))
  )(
    new Set(moderatorVersionIds)
  );

  // 5. Search using created_at_from/created_at_to filtering
  const from = modEdit1.created_at;
  const to = modEdit2.created_at;
  const byTime = await api.functional.discussionBoard.moderator.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      created_at_from: from,
      created_at_to: to
    }
  });
  typia.assert(byTime);
  TestValidator.predicate("versions in date range")(
    byTime.data.every(ver => ver.created_at >= from && ver.created_at <= to)
  );

  // 6. Search using content substring filter
  const substring = "edit version 1";
  const byContent = await api.functional.discussionBoard.moderator.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      content_contains: substring
    }
  });
  typia.assert(byContent);
  TestValidator.predicate("content substring matches")(
    byContent.data.every(ver => ver.content.includes(substring))
  );

  // 7. Pagination logic check (simulate limit 1)
  const paged = await api.functional.discussionBoard.moderator.comments.versions.search(connection, {
    commentId: comment.id,
    body: {
      // No explicit fields: assuming pagination by page/limit is supported through another means if not in DTO.
      editor_member_id: moderatorId
    }
  });
  typia.assert(paged);
  TestValidator.equals("pagination data type check")(typeof paged.pagination.current)("number");

  // 8. Error: search on invalid commentId (should error)
  await TestValidator.error("invalid commentId should fail")(
    async () => {
      await api.functional.discussionBoard.moderator.comments.versions.search(connection, {
        commentId: typia.random<string & tags.Format<"uuid">>(), // random value not associated with a real comment
        body: {}
      });
    }
  );
}

