 *    - is_deleted: true                  => should only return the deleted comment
 *    - is_deleted: false                 => should only return the non-deleted comment
 *    - created_at_from/created_at_to     => narrow for exact match
 *    - updated_at_from/updated_at_to     => for edge case window
 *    - (negative) is_deleted with a date range of no expected results
 * 8. Asserts results match expectations for each filter mode, checking:
 *    - Only the proper comment(s) are returned
 *    - Pagination and data format is valid
 *    - Edge case (no match) returns an empty data array
 */
export async function test_api_discussionBoard_test_moderator_filter_comments_by_deleted_status_and_date(
  connection: api.IConnection,
) {
  // 1. Add test member
  const testUserIdentifier = `testuser_${RandomGenerator.alphaNumeric(8)}`;
  const addMember = await api.functional.discussionBoard.admin.members.create(connection, {
    body: {
      user_identifier: testUserIdentifier,
      joined_at: new Date().toISOString(),
    }
  });
  typia.assert(addMember);
  // 2. Create topic (requires a random but valid category UUID)
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const topicTitle = `E2E Topic ${RandomGenerator.alphabets(6)}`;
  const topic = await api.functional.discussionBoard.member.topics.create(connection, {
