  const threadTitle = `E2E Thread ${RandomGenerator.alphabets(6)}`;
  const thread = await api.functional.discussionBoard.member.topics.threads.create(connection, {
    topicId: topic.id,
    body: {
      title: threadTitle,
    }
  });
