  const postContent = `This is a post for E2E comment filter testing at ${new Date().toISOString()}`;
  const post = await api.functional.discussionBoard.member.threads.posts.create(connection, {
    threadId: thread.id,
    body: {
      discussion_board_thread_id: thread.id,
      body: postContent,
    }
  });
