  const nonDeletedResult = await api.functional.discussionBoard.moderator.comments.search(connection, {
    body: {
      is_deleted: false,
      post_id: post.id,
    }
  });
  typia.assert(nonDeletedResult);
  TestValidator.equals("non-deleted comment search - count")(nonDeletedResult.data.length)(1);
  TestValidator.equals("non-deleted comment search - id")(nonDeletedResult.data[0].id)(commentOne.id);
  // 9. Moderator: filter by date window for created_at for one known comment
  const from = commentOne.created_at;
  const to = commentOne.created_at;
  const dateFiltered = await api.functional.discussionBoard.moderator.comments.search(connection, {
    body: {
      post_id: post.id,
      created_at_from: from,
      created_at_to: to,
    }
  });
  typia.assert(dateFiltered);
  TestValidator.predicate("date-filtered comment search - should have at least one")(
    dateFiltered.data.length >= 1
  );
  // 10. Moderator: filter for edge case (no match)
  const noMatch = await api.functional.discussionBoard.moderator.comments.search(connection, {
    body: {
      post_id: post.id,
      is_deleted: true,
      created_at_from: new Date(Date.now() + 24*3600*1000).toISOString(), // future date
      created_at_to: new Date(Date.now() + 48*3600*1000).toISOString(),
    }
  });
  typia.assert(noMatch);
  TestValidator.equals("no match for filter request")(noMatch.data.length)(0);
