 * with correct visibility and data counting.
 *
 * 1. Create several board members (admin-level API)
 * 2. As each member, create a report (member-level API) for various content (simulate both 'post' and 'comment')
 * 3. As admin, fetch the entire list of reports
 * 4. Verify that report summary fields are correct and all reports are present in the list
 * 5. Check that pagination information reflects number of created reports
 */
export async function test_api_discussionBoard_test_list_reports_as_admin_with_multiple_reports(
  connection: api.IConnection,
) {
  // 1. Create 3 board members
  const members = await Promise.all(
    ArrayUtil.repeat(3)(async () => {
      const createMember = await api.functional.discussionBoard.admin.members.create(connection, {
        body: {
          user_identifier: RandomGenerator.alphabets(8),
          joined_at: new Date().toISOString(),
        } satisfies IDiscussionBoardMember.ICreate,
      });
      typia.assert(createMember);
      return createMember;
    })
  );

  // 2. As each member, create a report, simulating both post and comment reports
  const createdReports = [];
  for (let i = 0; i < members.length; ++i) {
    // Simulate for variety: alternate post/comment
    const contentType = i % 2 === 0 ? 'post' : 'comment';
    const createReport = await api.functional.discussionBoard.member.reports.create(connection, {
      body: {
        reporter_id: members[i].id,
        content_type: contentType,
        reported_post_id: contentType === 'post' ? typia.random<string & tags.Format<'uuid'>>() : null,
        reported_comment_id: contentType === 'comment' ? typia.random<string & tags.Format<'uuid'>>() : null,
        reason: `Test report reason ${i}`,
      } satisfies IDiscussionBoardReport.ICreate,
    });
    typia.assert(createReport);
    createdReports.push(createReport);
  }

  // 3. As admin, fetch the paginated list of reports
  const page = await api.functional.discussionBoard.admin.reports.index(connection);
  typia.assert(page);

  // 4. Verify: All reports are found (by id)
  for (const created of createdReports) {
    const found = page.data.find((item) => item.id === created.id);
    TestValidator.predicate(`report with id=${created.id} is present`)(!!found);
    if (found) {
      // Verify summary fields
      TestValidator.equals('content_type')(found.content_type)(created.content_type);
      TestValidator.equals('status')(found.status)(created.status);
      TestValidator.equals('reporter_id')(found.reporter_id)(created.reporter_id);
      // Check target id (flexible depending on post or comment)
      if (created.content_type === 'post') {
        TestValidator.equals('target_id === reported_post_id')(found.target_id)(created.reported_post_id);
      } else {
        TestValidator.equals('target_id === reported_comment_id')(found.target_id)(created.reported_comment_id);
      }
    }
  }

  // 5. Verify pagination fields reflect the number of created reports (may include pre-existing, check at least ours present)
  TestValidator.predicate('pagination.records >= reports created')(page.pagination.records >= createdReports.length);
}

