 * 3. (Optional) Create another unrelated root category and child, to ensure unrelated categories don't appear in filtered results.
 * 4. Use the PATCH /discussionBoard/categories endpoint to search by the known root's id as parent_id and a date range that includes only a subset of the children.
 * 5. Validate that only the expected children are returned (by id/name), no unrelated categories are present, and that pagination/info matches expected numbers.
 * 6. Run further searches with narrower date ranges and/or sort reverse order, to verify sorting and pagination as well.
 *
 * Focus on end-to-end workflow and result validation, not internal DB state.
 */
export async function test_api_discussionBoard_test_advanced_filter_categories_by_parent_id_and_date_range(
  connection: api.IConnection,
) {
