import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * 감사 로그 생성시 필수 필드 유효성 검증 테스트
 *
 * 관리자 권한으로 감사 로그를 생성 시도를 하면서, 필수 필드(action_type 등) 누락 시 서버가 요청을 거부하고 유효성 에러를
 * 반환하는지 검증합니다. 이를 통해 모든 필수 감사 로그 메타데이터가 비워질 수 없으며, 올바른 입력이 필요하다는 비즈니스 규칙이 지켜짐을
 * 확인합니다.
 *
 * 테스트 흐름:
 *
 * 1. 필수 필드(action_type)를 누락하고 생성 시도 → 에러 반환 기대
 * 2. Action_type만으로 최소 생성 가능 → 성공 기대
 * 3. 선택 필드를 null로 전달해 생성 → 성공 및 null 처리 확인
 * 4. 모든 필드를 채워서 생성 → 성공 및 저장 값 검증
 */
export async function test_api_discussionBoard_admin_auditLogs_create_validation(
  connection: api.IConnection,
) {
  // 1. 필수 필드(action_type) 누락: 생성 불가/에러 검증
  await TestValidator.error("action_type 누락시 에러")(async () => {
    await api.functional.discussionBoard.admin.auditLogs.create(connection, {
      body: {
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        target_id: typia.random<string & tags.Format<"uuid">>(),
        // action_type 일부러 제외
        action_detail: "action_type 필드 누락 테스트",
      },
    });
  });

  // 2. 필수 값만 입력 → 정상 생성
  const minimal = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    {
      body: {
        action_type: "assign_moderator",
      },
    },
  );
  typia.assert(minimal);
  TestValidator.equals("action_type 값")(minimal.action_type)(
    "assign_moderator",
  );

  // 3. 선택 필드를 모두 null로 채워서 생성
  const nullCase = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    {
      body: {
        action_type: "policy_change",
        actor_id: null,
        target_id: null,
        action_detail: null,
      },
    },
  );
  typia.assert(nullCase);
  TestValidator.equals("action_type 값")(nullCase.action_type)("policy_change");
  TestValidator.equals("actor_id nul 체크")(nullCase.actor_id)(null);
  TestValidator.equals("target_id null 체크")(nullCase.target_id)(null);
  TestValidator.equals("action_detail null 체크")(nullCase.action_detail)(null);

  // 4. 모든 필드 입력 정상 생성
  const complete = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    {
      body: {
        action_type: "user_ban",
        actor_id: typia.random<string & tags.Format<"uuid">>(),
        target_id: typia.random<string & tags.Format<"uuid">>(),
        action_detail: "반복적인 정책 위반으로 계정 정지 처리.",
      },
    },
  );
  typia.assert(complete);
  TestValidator.equals("action_type 매칭")(complete.action_type)("user_ban");
  TestValidator.equals("action_detail 매칭")(complete.action_detail)(
    "반복적인 정책 위반으로 계정 정지 처리.",
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";

/**
 * Validate that non-admins cannot delete audit logs (authorization
 * enforcement).
 *
 * Business Context: Audit logs contain critical security/compliance records and
 * must not be alterable except by admins. This test ensures the delete endpoint
 * enforces admin-only access, denying delete operations from non-admin users.
 *
 * Workflow:
 *
 * 1. As admin, create a new audit log entry to obtain a valid auditLogId
 *    (dependency).
 * 2. (Simulate) switch to a connection context without admin privileges.
 * 3. Attempt to delete the audit log entry just created.
 * 4. Assert that an authorization error (forbidden/unauthorized) is thrown,
 *    confirming that only admins can delete audit logs.
 *
 * Notes:
 *
 * - No attempt to test with invalid auditLogId (that would be a different test).
 * - Assumes role-switch uses existing connection/session mechanics.
 */
export async function test_api_discussionBoard_test_delete_audit_log_without_admin_role_returns_forbidden(
  connection: api.IConnection,
) {
  // 1. Create an audit log entry as admin (dependency)
  const auditLog = await api.functional.discussionBoard.admin.auditLogs.create(
    connection,
    {
      body: {
        action_type: "test_non_admin_delete",
        actor_id: null,
        target_id: null,
        action_detail: "Testing delete prohibition for non-admins",
      } satisfies IDiscussionBoardAuditLog.ICreate,
    },
  );
  typia.assert(auditLog);

  // 2. (Simulate) use non-admin role by clearing Authorization header
  const nonAdminConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };

  // 3. Attempt to delete the audit log as non-admin and assert forbidden error
  await TestValidator.error(
    "Non-admin should not be able to delete audit logs",
  )(async () => {
    await api.functional.discussionBoard.admin.auditLogs.erase(
      nonAdminConnection,
      { auditLogId: auditLog.id },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPageIDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardSystemNotice";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * Validate system notice listing (as admin) with simulated filtering and
 * pagination.
 *
 * This test evaluates listing the system notices as an admin user, after
 * seeding the database with a diverse set of notices. It simulates a realistic
 * moderation/operations workflow:
 *
 * 1. Seed at least two categories with random UUIDs (no category creation API
 *    provided, so UUIDs are generated).
 * 2. Create a variety of system notices—global and per-category, active/inactive,
 *    and scheduled—covering a broad range of states.
 * 3. Attempt to test pagination and filtering as described in scenario (note: SDK
 *    does not allow page/filter params, so test presence/structure indirectly
 *    by checking result content).
 * 4. Validate that the listing response reflects correct record count, pagination
 *    info, and presence/accuracy of seeded data.
 * 5. Assert that returned instances match the schema/types and that pagination
 *    meta is consistent with the created notices.
 * 6. Document limitations openly in code for future feature/test expansion (when
 *    filtering/paging params are supported by SDK).
 */
export async function test_api_discussionBoard_test_list_system_notices_as_admin_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // Step 1: Seed two random category UUIDs
  const categoryA = typia.random<string & tags.Format<"uuid">>();
  const categoryB = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Create system notices across categories/status/scheduled states
  const makeNotice = async (body: IDiscussionBoardSystemNotice.ICreate) =>
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body },
    );

  const now = new Date();
  const future = new Date(now.getTime() + 86400 * 1000).toISOString();

  const notices = [
    // Global, active now
    await makeNotice({
      title: "Global Active Now",
      body: "Body1",
      is_active: true,
    }),
    // Global, active, scheduled for future
    await makeNotice({
      title: "Global Active Future",
      body: "Body2",
      is_active: true,
      start_at: future,
    }),
    // CategoryA, active
    await makeNotice({
      title: "CatA Active1",
      body: "Body3",
      is_active: true,
      category_id: categoryA,
    }),
    await makeNotice({
      title: "CatA Active2",
      body: "SearchTarget",
      is_active: true,
      category_id: categoryA,
    }),
    // CategoryB, active
    await makeNotice({
      title: "CatB Active1",
      body: "Body5",
      is_active: true,
      category_id: categoryB,
    }),
    // CategoryB, inactive
    await makeNotice({
      title: "CatB Inactive",
      body: "Body6",
      is_active: false,
      category_id: categoryB,
    }),
    // Global, inactive
    await makeNotice({
      title: "Global Inactive",
      body: "Body7",
      is_active: false,
    }),
    // CategoryA, inactive
    await makeNotice({
      title: "CatA Inactive",
      body: "Body8",
      is_active: false,
      category_id: categoryA,
    }),
  ];
  notices.forEach(typia.assert);

  // Step 3: List system notices using admin list endpoint
  const output =
    await api.functional.discussionBoard.admin.systemNotices.index(connection);
  typia.assert(output);

  // Step 4: Basic meta and data assertions
  TestValidator.predicate("system notice list is not empty")(
    output.data.length > 0,
  );
  TestValidator.equals("pagination records count")(output.pagination.records)(
    notices.length,
  );
  TestValidator.predicate("pagination meta fields valid")(
    typeof output.pagination.current === "number" &&
      typeof output.pagination.limit === "number" &&
      typeof output.pagination.records === "number" &&
      typeof output.pagination.pages === "number",
  );
  // Each returned object matches type
  output.data.forEach(typia.assert);

  // Step 5: Indirect presence check for category filtering & text search
  TestValidator.predicate("has at least 1 CatA notice")(
    output.data.some((n) => n.category_id === categoryA),
  );
  TestValidator.predicate("has at least 1 CatB notice")(
    output.data.some((n) => n.category_id === categoryB),
  );
  TestValidator.predicate("has at least 1 global notice")(
    output.data.some((n) => !n.category_id),
  );
  TestValidator.predicate("has at least 1 SearchTarget title")(
    output.data.some((n) => n.title.includes("SearchTarget")),
  );

  // Step 6: Notes on limits
  // Current index endpoint has no querystring support for paging or filters; re-run is a full list.
  // Tests for page limiting, custom page, or explicit filtering must be expanded once SDK supports such params.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
