        nonAdminConnection,
        {
          moderatorId: moderator.id,
          body: {
            revoked_at: new Date().toISOString(),
          } satisfies IDiscussionBoardModerator.IUpdate,
        },
      );
    },
  );

  // 3. (Admin) Update moderator back with valid admin connection, expect success
  const updateInput: IDiscussionBoardModerator.IUpdate = {
    revoked_at: null, // Unset revocation (if needed)
    granted_at: new Date().toISOString(),
  };
  const updated = await api.functional.discussionBoard.admin.moderators.update(
    connection,
    {
      moderatorId: moderator.id,
      body: updateInput,
    },
  );
  typia.assert(updated);
  TestValidator.equals("correct moderator")(updated.id)(moderator.id);
  TestValidator.equals("user identifier")(updated.user_identifier)(
    moderator.user_identifier,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";

/**
 * 관리자에 의한 활동 로그 생성 및 오류 케이스 검증
 *
 * 이 테스트는 관리자가 새 활동 로그 레코드를 올바르게 생성할 수 있는지 확인합니다. 필수 입력 필드(행위자, 활동유형, 시각 등)가
 * 정상적으로 검증되어야 하며, 생성 결과의 스키마, 필드 저장, 감사 목적의 기록 등록 여부를 모두 확인합니다. 또한, 필수 입력값
 * 누락·포맷 오류·존재하지 않는 참조값(예: actor_id, target_id 등)·관리자 권한이 아닌 요청에 대해 적절하게 실패하는지
 * 런타임 오류 테스트도 포함합니다.
 *
 * 테스트 단계:
 *
 * 1. 정상 관리자 계정에서 필수·권장값을 모두 입력해 활동 로그 생성 성공을 확인
 * 2. 필수 입력 누락(예: actor_id 없음)시 런타임 에러 확인
 * 3. 존재하지 않는 actor_id, 또는 유효하지 않은 참조값 입력 시 에러 확인
 * 4. 관리자 권한 없는(비인증) 상태에서 요청 시 에러 확인
 *
 * 부가적으로, 생성한 로그의 주요 필드와 감사 목적의 저장 여부, 스키마 유효성(assert)까지 검증
 */
export async function test_api_discussionBoard_test_create_activity_log_admin_success_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. 정상 관리자 계정에서 정상 입력으로 활동 로그 생성 성공
  const now = new Date().toISOString();
  const actorId = typia.random<string & tags.Format<"uuid">>();
  const logInput: IDiscussionBoardActivityLog.ICreate = {
    actor_id: actorId,
    actor_type: "admin",
    action_type: "board_locked",
    action_timestamp: now,
    ip_address: "192.168.0.1",
    user_agent: "Mozilla/5.0 (E2E-Test)",
    topic_id: typia.random<string & tags.Format<"uuid">>(),
    thread_id: null,
    post_id: null,
    metadata_json: JSON.stringify({ reason: "Test E2E log", severity: "high" }),
  };
  const createdLog =
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: logInput,
    });
  typia.assert(createdLog);
  TestValidator.equals("actor reference")(createdLog.actor_id)(actorId);
  TestValidator.equals("type matches")(createdLog.actor_type)("admin");
  TestValidator.equals("action matches")(createdLog.action_type)(
    "board_locked",
  );
  TestValidator.equals("timestamp matches")(createdLog.action_timestamp)(now);

  // 2. 필수 입력값 누락(actor_id 없음) - 런타임 오류
  await TestValidator.error("require actor_id fail")(async () => {
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        ...logInput,
        actor_id: undefined as any,
      },
    });
  });

  // 3. 존재하지 않는 actor_id 입력(가정: 시스템에 없는 actor UUID) - 에러 기대
  await TestValidator.error("nonexistent actor_id fail")(async () => {
    await api.functional.discussionBoard.admin.activityLogs.create(connection, {
      body: {
        ...logInput,
        actor_id: "11111111-1111-1111-1111-111111111111" as any,
      },
    });
  });

  // 4. 비인증 요청(관리자 인증 없이 시도) - connection에서 인증헤더 삭제 후 시도
  const noAuthConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete noAuthConnection.headers["Authorization"];
  await TestValidator.error("unauthorized fail")(async () => {
    await api.functional.discussionBoard.admin.activityLogs.create(
      noAuthConnection,
      {
        body: logInput,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IPageIDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMember";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test admin advanced search/filter and pagination for discussion board
 * members.
 *
 * This test ensures that an admin can:
 *
 * 1. Filter members by suspension status (suspended, active)
 * 2. Search by user_identifier field
 * 3. Apply pagination and verify correct paging mechanics
 *
 * Steps:
 *
 * 1. Create 8 members with distinct user_identifiers and varied join dates. (No
 *    direct API support for setting suspension, so test will only validate
 *    what's possible.)
 * 2. Search by user_identifier, verifying a unique match.
 * 3. Test pagination by requesting small page sizes and checking results and
 *    metadata consistency.
 *
 * Note: As no endpoint for directly suspending members exists in the input set,
 * suspension filter tests are omitted.
 */
export async function test_api_discussionBoard_test_search_members_by_status_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create 8 members with unique user_identifiers
  const identifiers: string[] = ArrayUtil.repeat(8)(() =>
    RandomGenerator.alphaNumeric(8),
  );
  const joinedAts: string[] = ArrayUtil.repeat(8)(() =>
    new Date(
      Date.now() - RandomGenerator.integer(0)(60 * 60 * 24 * 10 * 1000),
    ).toISOString(),
  );
  for (let i = 0; i < 8; ++i) {
    const member = await api.functional.discussionBoard.admin.members.create(
      connection,
      {
        body: {
          user_identifier: identifiers[i],
          joined_at: joinedAts[i],
        } satisfies IDiscussionBoardMember.ICreate,
      },
    );
    typia.assert(member);
  }

  // 2. Search by user_identifier (should match only 1 member)
  const matchIdentifier = identifiers[2];
  const byIdRes = await api.functional.discussionBoard.admin.members.search(
    connection,
    {
      body: {
        user_identifier: matchIdentifier,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(byIdRes);
  TestValidator.predicate("user_identifier unique match")(
    byIdRes.data.length === 1 &&
      byIdRes.data[0].user_identifier === matchIdentifier,
  );

  // 3. Pagination logic: page size 3 for >2 pages
  const pageSize = 3;
  // Page 1
  const page1 = await api.functional.discussionBoard.admin.members.search(
    connection,
    {
      body: {
        page: 1,
        limit: pageSize,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals("pagination page1 data count")(page1.data.length)(
    pageSize,
  );
  TestValidator.equals("pagination page1 meta")(page1.pagination.current)(1);
  // Page 2
  const page2 = await api.functional.discussionBoard.admin.members.search(
    connection,
    {
      body: {
        page: 2,
        limit: pageSize,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(page2);
  TestValidator.equals("pagination page2 data count")(page2.data.length)(
    pageSize,
  );
  TestValidator.equals("pagination page2 meta")(page2.pagination.current)(2);
  // Page 3 (may have < pageSize if 8 members)
  const page3 = await api.functional.discussionBoard.admin.members.search(
    connection,
    {
      body: {
        page: 3,
        limit: pageSize,
      } satisfies IDiscussionBoardMember.IRequest,
    },
  );
  typia.assert(page3);
  TestValidator.predicate("pagination last page count")(
    page3.data.length <= pageSize && page3.pagination.current === 3,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
