import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIDiscussionBoardPostAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPostAttachment";

/**
 * 게시글 첨부파일 검색에서 조건에 맞지 않는 경우(검색 결과가 없는 상황)를 검증합니다.
 *
 * 이 테스트는 실제 첨부파일이 여러 개 존재하는 게시글에서, 존재하지 않는 파일명 또는 존재하지 않는 MIME 타입으로 첨부파일 검색 시,
 * 결과 data 배열이 비어 있는지 (empty array) 반환되는지 확인합니다.
 *
 * **비즈니스 플로우**
 *
 * 1. 테스트용 임의 threadId를 준비합니다.
 * 2. 해당 스레드에 게시글을 작성합니다.
 * 3. 작성한 게시글에 첨부파일 3개를 각각 file_name/mime_type 다르게 업로드합니다.
 * 4. 첨부파일 전체 검색으로 업로드된 첨부파일 개수(3개) 정상 확인
 * 5. 존재하지 않는 랜덤한 file_name으로 첨부파일 검색 → data가 빈 배열인지 검증
 * 6. 존재하지 않는 마임타입으로 첨부파일 검색 → data가 빈 배열인지 검증
 */
export async function test_api_discussionBoard_test_search_post_attachments_with_no_results(
  connection: api.IConnection,
) {
  // 1. 테스트용 임의 threadId를 준비
  const threadId = typia.random<string & tags.Format<"uuid">>();

  // 2. 게시글 작성 (임의 threadId)
  const post = await api.functional.discussionBoard.member.threads.posts.create(
    connection,
    {
      threadId,
      body: {
        discussion_board_thread_id: threadId,
        body: RandomGenerator.content()()(),
      },
    },
  );
  typia.assert(post);

  // 3. 첨부파일 3개 업로드 (file_name, mime_type 다양하게)
  const attachments = await Promise.all(
    [0, 1, 2].map((n) =>
      api.functional.discussionBoard.member.posts.attachments.create(
        connection,
        {
          postId: post.id,
          body: {
            discussion_board_post_id: post.id,
            uploader_member_id: post.creator_member_id,
            file_uri: `https://files.example.com/sample${n}.bin`,
            file_name: `testfile_${n}_${RandomGenerator.alphaNumeric(12)}`,
            mime_type:
              n === 0
                ? "image/png"
                : n === 1
                  ? "application/pdf"
                  : "text/plain",
          },
        },
      ),
    ),
  );
  attachments.forEach(typia.assert);

  // 4. 첨부파일 전체 검색: 실제 3개 등록되어 있음을 보장
  const allAttachments =
    await api.functional.discussionBoard.posts.attachments.search(connection, {
      postId: post.id,
      body: {},
    });
  typia.assert(allAttachments);
  TestValidator.equals("첨부파일 총 3개 생성 확인")(allAttachments.data.length)(
    3,
  );

  // 5. 존재하지 않는 파일명으로 검색 → empty array 조건 검증
  const rareFileName = `notfound_${RandomGenerator.alphaNumeric(24)}`;
  const searchByRareName =
    await api.functional.discussionBoard.posts.attachments.search(connection, {
      postId: post.id,
      body: { file_name: rareFileName },
    });
  typia.assert(searchByRareName);
  TestValidator.equals("결과 없음 - file_name에 매칭되는 첨부 없음")(
    searchByRareName.data,
  )([]);

  // 6. 존재하지 않는 mime_type으로 검색 요청
  const impossibleMimeType = "application/x-nope-does-not-exist";
  const searchByImpossibleMime =
    await api.functional.discussionBoard.posts.attachments.search(connection, {
      postId: post.id,
      body: { mime_type: impossibleMimeType },
    });
  typia.assert(searchByImpossibleMime);
  TestValidator.equals("결과 없음 - mime_type 매칭 없음")(
    searchByImpossibleMime.data,
  )([]);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";

/**
 * Validate that a moderator cannot update immutable fields of a comment
 * attachment.
 *
 * Scenario: A comment is created by a member and an attachment is uploaded. A
 * moderator then attempts to update this attachment with fields that must not
 * be allowed to change (e.g., upload timestamp and foreign key IDs). The API
 * should reject this attempt with a validation error indicating forbidden
 * updates to immutable fields.
 *
 * Steps:
 *
 * 1. Create a member account (as admin) to be the comment and attachment author.
 * 2. Create a comment as the member (with a random parent post ID).
 * 3. Upload an attachment (with all required fields) as that member.
 * 4. Create a moderator account (as admin) and grant moderation rights.
 * 5. As moderator, attempt to update the attachment, sending a payload that tries
 *    to change immutable fields (e.g., discussion_board_comment_id,
 *    uploader_member_id, uploaded_at).
 * 6. Verify that the API rejects the update with a validation error (check that an
 *    error is thrown by the SDK function call).
 * 7. Also confirm that the attachment remains unchanged by attempting a valid
 *    metadata update and checking normal behavior.
 */
export async function test_api_discussionBoard_test_update_comment_attachment_by_moderator_with_invalid_fields_fails(
  connection: api.IConnection,
) {
  // 1. Create member (admin API)
  const user_identifier = RandomGenerator.email();
  const joined_at = new Date().toISOString();
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier,
        joined_at,
      },
    },
  );
  typia.assert(member);

  // 2. Create comment as the member
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: member.id,
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
        content: RandomGenerator.paragraph()(),
      },
    },
  );
  typia.assert(comment);

  // 3. Upload an attachment for that comment
  const attachment =
    await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          uploader_member_id: member.id,
          file_name: "test-file.png",
          file_url: "https://cdn.example.com/test-file.png",
          mime_type: "image/png",
        },
      },
    );
  typia.assert(attachment);

  // 4. Create moderator (admin API)
  const moderator_user_identifier = RandomGenerator.email();
  const granted_at = new Date().toISOString();
  const moderator =
    await api.functional.discussionBoard.admin.moderators.create(connection, {
      body: {
        user_identifier: moderator_user_identifier,
        granted_at,
        revoked_at: null,
      },
    });
  typia.assert(moderator);

  // 5. As moderator, attempt forbidden update on the attachment
  await TestValidator.error(
    "moderator cannot update immutable attachment fields",
  )(async () => {
    await api.functional.discussionBoard.moderator.comments.attachments.update(
      connection,
      {
        commentId: attachment.discussion_board_comment_id,
        attachmentId: attachment.id,
        // Purposely cast payload as any to include a forbidden field not supported by IUpdate.
        body: {
          uploaded_at: new Date().toISOString(), // not allowed
        } as any,
      },
    );
  });

  // 6. As moderator, perform a valid update and verify no error
  const new_file_name = "file-corrected.pdf";
  const updated =
    await api.functional.discussionBoard.moderator.comments.attachments.update(
      connection,
      {
        commentId: attachment.discussion_board_comment_id,
        attachmentId: attachment.id,
        body: {
          file_name: new_file_name,
        },
      },
    );
  typia.assert(updated);
  TestValidator.equals("file name updated")(updated.file_name)(new_file_name);
}

