import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that searching activity logs as a non-admin user is properly
 * forbidden.
 *
 * This test confirms that system security boundaries are enforced: non-admin
 * members may not access advanced audit log search functionality via the admin
 * endpoint for activity logs.
 *
 * Test Scenario:
 *
 * 1. Admin creates a regular member using the admin-only registration endpoint.
 * 2. Simulate a member session by removing admin privileges from the API
 *    connection.
 * 3. Attempt to perform a PATCH search for activity logs (admin endpoint) with
 *    this downgraded session.
 * 4. Assert that access is denied by verifying that an error is thrown.
 *
 * This negative test ensures sensitive audit operations are protected strictly
 * for admins, and verifies that accidental privilege escalation is not
 * possible.
 */
export async function test_api_discussionBoard_test_activity_logs_search_forbidden_for_non_admins(
  connection: api.IConnection,
) {
  // 1. Admin creates a new member via the admin-only endpoint
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: RandomGenerator.alphabets(12),
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Simulate a member session by removing admin Authorization from connection
  const memberConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined, // Simulates a basic (non-admin) session
    },
  };

  // 3. Attempt to access activity logs search as a non-admin (should be forbidden)
  await TestValidator.error("activity log search forbidden for non-admin")(
    async () => {
      await api.functional.discussionBoard.admin.activityLogs.search(
        memberConnection,
        {
          body: {}, // No filters; any call must be rejected as non-admin
        },
      );
    },
  );
}

