import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTopics } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTopics";
import type { IDiscussionBoardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThreads";
import type { IPageIDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardPost";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";

/**
 * Validate that listing posts in a member-only discussion thread requires
 * authentication.
 *
 * This test verifies the system enforces access control on confidential thread
 * content.
 *
 * Step-by-step process:
 *
 * 1. Create a discussion topic as a member (requires authentication)
 * 2. Create a thread under that topic as a member
 * 3. Add at least one post to the thread as a member
 * 4. Simulate guest access by removing authentication information
 * 5. Attempt to list the posts in the thread as a guest (unauthenticated user)
 * 6. Confirm that an authentication/authorization error is thrown — access must be
 *    denied
 */
export async function test_api_discussionBoard_test_list_posts_in_thread_requires_membership(
  connection: api.IConnection,
) {
  // 1. Create a topic as a member
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const topic = await api.functional.discussionBoard.member.topics.create(
    connection,
    {
      body: {
        title: RandomGenerator.paragraph()(),
        description: RandomGenerator.content()()(),
        pinned: false,
        closed: false,
        discussion_board_category_id: categoryId,
      } satisfies IDiscussionBoardTopics.ICreate,
    },
  );
  typia.assert(topic);

  // 2. Create a thread as a member
  const thread =
    await api.functional.discussionBoard.member.topics.threads.create(
      connection,
      {
        topicId: topic.id,
        body: {
          title: RandomGenerator.paragraph()(),
        } satisfies IDiscussionBoardThreads.ICreate,
      },
    );
  typia.assert(thread);

  // 3. Add at least one post to the thread as a member
  const post = await api.functional.discussionBoard.member.threads.posts.create(
    connection,
    {
      threadId: thread.id,
      body: {
        discussion_board_thread_id: thread.id,
        body: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 4. Simulate guest access by clearing authentication header
  const guestConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete guestConnection.headers.Authorization;

  // 5. Attempt to list posts as guest; expect error
  TestValidator.error("guest cannot list posts in member-only thread")(() =>
    api.functional.discussionBoard.member.threads.posts.index(guestConnection, {
      threadId: thread.id,
    }),
  );
}

