import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSetting";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";
import type { IPageIDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced search and filter functionality for audit logs
 * (discussion_board_audit_logs).
 *
 * This scenario tests that searching with complex filters such as actor_id,
 * action_type, and date ranges returns the correct filtered and paginated
 * results.
 *
 * Prerequisite: At least two audit log entries must exist, each with distinct
 * actor_id and action_type values. This is achieved by creating two board
 * settings with different keys and values.
 *
 * Steps:
 *
 * 1. Create first board setting (expect audit log generated for this action)
 * 2. Create second board setting (expect second, different audit log entry)
 * 3. Query audit logs for all records: validate at least the two generated logs
 *    exist; extract actor_id, action_type, created_at
 * 4. Filter by actor_id of first log: verify only logs for that actor are included
 * 5. Filter by action_type of second log: verify only logs for that action_type
 *    are included
 * 6. Filter by date range (created_at_from, created_at_to) encompassing only the
 *    second log: verify only that log is returned
 * 7. Validate pagination (limit=1): ensure paging info and only one record
 *    returned
 */
export async function test_api_discussionBoard_test_search_audit_logs_with_advanced_filters(
  connection: api.IConnection,
) {
  // 1. Create the first unique board setting
  const setting1 = await api.functional.discussionBoard.admin.settings.create(
    connection,
    {
      body: {
        setting_key: `scenario1_${RandomGenerator.alphaNumeric(8)}`,
        setting_value: RandomGenerator.alphaNumeric(10),
        description: "Scenario test 1",
      },
    },
  );
  typia.assert(setting1);

  // 2. Create the second unique board setting (distinct value)
  const setting2 = await api.functional.discussionBoard.admin.settings.create(
    connection,
    {
      body: {
        setting_key: `scenario2_${RandomGenerator.alphaNumeric(8)}`,
        setting_value: RandomGenerator.alphaNumeric(10),
        description: "Scenario test 2",
      },
    },
  );
  typia.assert(setting2);

  // 3. Query all audit logs (no filters) to find relevant log entries
  const allLogsResponse =
    await api.functional.discussionBoard.admin.auditLogs.search(connection, {
      body: {}, // no filters - retrieve all
    });
  typia.assert(allLogsResponse);
  TestValidator.predicate("at least two logs exist")(
    allLogsResponse.data.length >= 2,
  );

  // Pick log entries related to setting1 and setting2 (by target_id, action_type, actor_id, etc.)
  // As audit log spec is generic, pick logs where target_id == setting1.id or setting2.id
  const logEntry1 = allLogsResponse.data.find(
    (l) => l.target_id === setting1.id,
  );
  const logEntry2 = allLogsResponse.data.find(
    (l) => l.target_id === setting2.id,
  );
  TestValidator.predicate("setting1 log exists")(!!logEntry1);
  TestValidator.predicate("setting2 log exists")(!!logEntry2);
  // Defensive: set up for later filters
  if (!logEntry1 || !logEntry2)
    throw new Error("Required audit logs for test setup missing");

  // 4. Filter by actor_id of first log (should include logEntry1, possibly others for same actor)
  const byActor = await api.functional.discussionBoard.admin.auditLogs.search(
    connection,
    {
      body: {
        actor_id: logEntry1.actor_id || null,
      },
    },
  );
  typia.assert(byActor);
  // All returned logs must be by this actor
  for (const log of byActor.data) {
    TestValidator.equals("actor_id matches")(log.actor_id)(logEntry1.actor_id);
  }

  // 5. Filter by action_type of the second log
  const byAction = await api.functional.discussionBoard.admin.auditLogs.search(
    connection,
    {
      body: {
        action_type: logEntry2.action_type,
      },
    },
  );
  typia.assert(byAction);
  for (const log of byAction.data) {
    TestValidator.equals("action_type matches")(log.action_type)(
      logEntry2.action_type,
    );
  }

  // 6. Filter by created_at range just for second log
  // Pick a 1-second window that should only include logEntry2
  const createdFrom = logEntry2.created_at;
  const createdTo = logEntry2.created_at;
  const byTime = await api.functional.discussionBoard.admin.auditLogs.search(
    connection,
    {
      body: {
        created_at_from: createdFrom,
        created_at_to: createdTo,
      },
    },
  );
  typia.assert(byTime);
  // All results should have created_at within range and include the target log
  for (const log of byTime.data) {
    TestValidator.predicate("created_at in window")(
      log.created_at >= createdFrom && log.created_at <= createdTo,
    );
  }
  TestValidator.predicate(
    "includes only logEntry2 or empty if strict filtering",
  )(byTime.data.length === 0 || byTime.data.some((l) => l.id === logEntry2.id));

  // 7. Validate pagination: limit=1 returns single record and correct pagination
  const paged = await api.functional.discussionBoard.admin.auditLogs.search(
    connection,
    {
      body: { limit: 1 },
    },
  );
  typia.assert(paged);
  TestValidator.equals("only one record returned")(paged.data.length)(1);
  TestValidator.equals("pagination shows limit=1")(paged.pagination.limit)(1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAuditLog";
import type { IPageIDiscussionBoardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 감사 로그 검색 시 잘못된 쿼리(예: 유효하지 않은 날짜 범위/미지원 필터 사용)를 보내면 검증 에러가 발생해야 함을 확인.
 *
 * - 비즈니스 목적: 운영 감사/보안 감사에서 필수로 검증되어야 할 입력 값 유효성, 필터 검증을 테스트함.
 * - 관리자는 로그인되어 있어야 하며 별도의 데이터 생성은 필요 없음.
 *
 * 테스트 순서:
 *
 * 1. (가정) 관리자가 이미 인증되어 있는 connection 제공, 별도의 인증 선행 테스트는 없음
 * 2. 날짜 범위를 역순(종료일이 시작일보다 이전)으로 요청 시도 => created_at_from > created_at_to
 * 3. Page, limit 음수 등 입력 불가 숫자 값
 * 4. 잘못된 uuid 포맷 값
 * 5. 각 쿼리 시도 후, 서버의 유효성 에러(HttpError 등)가 발생하는지 TestValidator.error로 검증
 * 6. 정상 응답(레코드 반환, 200 등)이 있으면 실패 처리
 *
 * 에러 메시지, status 등 세부 검증은 생략(단순 error 발생까지만 확인)
 */
export async function test_api_discussionBoard_test_search_audit_logs_with_invalid_query(
  connection: api.IConnection,
) {
  // 1. 날짜 범위가 비정상인 경우(예: created_at_from > created_at_to)
  const from = new Date("2025-09-01T00:00:00.000Z").toISOString();
  const to = new Date("2025-08-01T00:00:00.000Z").toISOString();

  await TestValidator.error(
    "Invalid date range: created_at_from > created_at_to",
  )(async () => {
    await api.functional.discussionBoard.admin.auditLogs.search(connection, {
      body: {
        created_at_from: from,
        created_at_to: to,
      },
    });
  });

  // 2. page, limit 음수 등 입력 불가 숫자 값
  await TestValidator.error("Invalid page/limit values (negative numbers)")(
    async () => {
      await api.functional.discussionBoard.admin.auditLogs.search(connection, {
        body: {
          page: -1 as any,
          limit: -1 as any,
        },
      });
    },
  );

  // 3. 잘못된 uuid 포맷 값
  await TestValidator.error("Invalid uuid format for actor_id")(async () => {
    await api.functional.discussionBoard.admin.auditLogs.search(connection, {
      body: {
        actor_id: "not-a-uuid" as any,
      },
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardActivityLog";
import type { IPageIDiscussionBoardActivityLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardActivityLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced activity log search with role and date filters for
 * moderator.
 *
 * 본 테스트는 관리자/모더레이터가 활동 로그를 actor_type(예: 'member'/'moderator') 및 시간 범위별로 고급
 * 검색(필터링)할 수 있음을 검증합니다. 또한 페이지네이션이 정상 동작하는지, 잘못된 입력/권한없는 요청/없는 역할명 등에서 예외처리가
 * 이루어지는지도 확인합니다.
 *
 * 절차:
 *
 * 1. 테스트 준비: 멤버/모더레이터 각각의 역할과 서로 다른 시각의 활동 로그 샘플 3건 생성
 * 2. Actor_type='member', 시간범위 내 로그만 필터하여 검색 → 결과에 사전 생성된 로그 포함 여부, 필터링 및 페이징 동작
 *    확인
 * 3. Limit=1로 요청시 한 페이지당 1건만 반환되는지 페이지네이션 확인
 * 4. Actor_type='moderator', 2025-07-15 하루만 범위로 필터 → 해당 role/date 로그만 반환되는지 확인
 * 5. Action_timestamp 잘못된 포맷으로 요청시 오류 반환하는지
 * 6. Authorization 없이 검색 시도시 권한 오류(접근 거부) 발생 확인
 * 7. Page=-1 또는 limit 과도(100만) 등 잘못된 값 입력시 예외 반환
 * 8. Actor_type='NOT_A_REAL_ROLE'(존재하지 않는 역할명)로 요청 시 결과 0건 반환
 */
export async function test_api_discussionBoard_test_search_activity_logs_with_role_and_date_filters(
  connection: api.IConnection,
) {
  // 1. 테스트 기본 데이터 입력: 멤버/모더레이터 각각, 서로 다른 시각에 생성
  const memberActorId = typia.random<string & tags.Format<"uuid">>();
  const moderatorActorId = typia.random<string & tags.Format<"uuid">>();

  const log1 =
    await api.functional.discussionBoard.moderator.activityLogs.create(
      connection,
      {
        body: {
          actor_id: memberActorId,
          actor_type: "member",
          action_type: "view_post",
          action_timestamp: "2025-07-10T10:00:00.000Z",
        } satisfies IDiscussionBoardActivityLog.ICreate,
      },
    );
  typia.assert(log1);

  const log2 =
    await api.functional.discussionBoard.moderator.activityLogs.create(
      connection,
      {
        body: {
          actor_id: moderatorActorId,
          actor_type: "moderator",
          action_type: "moderation_action",
          action_timestamp: "2025-07-15T12:00:00.000Z",
        } satisfies IDiscussionBoardActivityLog.ICreate,
      },
    );
  typia.assert(log2);

  const log3 =
    await api.functional.discussionBoard.moderator.activityLogs.create(
      connection,
      {
        body: {
          actor_id: memberActorId,
          actor_type: "member",
          action_type: "comment_created",
          action_timestamp: "2025-07-18T15:00:00.000Z",
        } satisfies IDiscussionBoardActivityLog.ICreate,
      },
    );
  typia.assert(log3);

  // 2. 'member' 역할 & 날짜범위로 검색(로그1/3만 포함돼야)
  const memberSearch =
    await api.functional.discussionBoard.moderator.activityLogs.search(
      connection,
      {
        body: {
          actor_type: "member",
          action_timestamp_from: "2025-07-09T00:00:00.000Z",
          action_timestamp_to: "2025-07-19T23:59:59.999Z",
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardActivityLog.IRequest,
      },
    );
  typia.assert(memberSearch);
  for (const log of memberSearch.data) {
    TestValidator.equals("actor_type is member")(log.actor_type)("member");
    TestValidator.predicate("timestamp in range")(
      log.action_timestamp >= "2025-07-09T00:00:00.000Z" &&
        log.action_timestamp <= "2025-07-19T23:59:59.999Z",
    );
  }
  TestValidator.predicate("contains setup logs")(
    memberSearch.data.some((x) => x.id === log1.id) &&
      memberSearch.data.some((x) => x.id === log3.id),
  );

  // 3. 페이지네이션 검증: limit=1 한정
  const paged =
    await api.functional.discussionBoard.moderator.activityLogs.search(
      connection,
      {
        body: {
          actor_type: "member",
          action_timestamp_from: "2025-07-09T00:00:00.000Z",
          action_timestamp_to: "2025-07-19T23:59:59.999Z",
          page: 1,
          limit: 1,
        } satisfies IDiscussionBoardActivityLog.IRequest,
      },
    );
  typia.assert(paged);
  TestValidator.equals("limit respected")(paged.data.length)(1);
  TestValidator.equals("pagination info")(paged.pagination.limit)(1);

  // 4. 'moderator' 역할, 하루 범위 필터
  const modSearch =
    await api.functional.discussionBoard.moderator.activityLogs.search(
      connection,
      {
        body: {
          actor_type: "moderator",
          action_timestamp_from: "2025-07-15T00:00:00.000Z",
          action_timestamp_to: "2025-07-15T23:59:59.999Z",
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardActivityLog.IRequest,
      },
    );
  typia.assert(modSearch);
  for (const log of modSearch.data) {
    TestValidator.equals("actor_type is moderator")(log.actor_type)(
      "moderator",
    );
    TestValidator.predicate("timestamp is 2025-07-15")(
      log.action_timestamp >= "2025-07-15T00:00:00.000Z" &&
        log.action_timestamp <= "2025-07-15T23:59:59.999Z",
    );
  }
  TestValidator.predicate("contains log2")(
    modSearch.data.some((x) => x.id === log2.id),
  );

  // 5. 잘못된 날짜 포맷 입력시 예외
  await TestValidator.error("invalid date format")(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(connection, {
      body: {
        actor_type: "member",
        action_timestamp_from: "2025-07-009T00:00:00",
        page: 1,
        limit: 10,
      } satisfies IDiscussionBoardActivityLog.IRequest,
    }),
  );

  // 6. 권한 없는 유저(Authorization 미포함) 검색시 권한거부 예외
  const anonConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: "" },
  };
  await TestValidator.error("unauthorized search should fail")(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(
      anonConnection,
      {
        body: {
          actor_type: "member",
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardActivityLog.IRequest,
      },
    ),
  );

  // 7. 음수 page, 과도한 limit
  await TestValidator.error("negative page")(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(connection, {
      body: {
        actor_type: "member",
        page: -1,
        limit: 10,
      } satisfies IDiscussionBoardActivityLog.IRequest,
    }),
  );
  await TestValidator.error("too large limit")(() =>
    api.functional.discussionBoard.moderator.activityLogs.search(connection, {
      body: {
        actor_type: "member",
        page: 1,
        limit: 1000000,
      } satisfies IDiscussionBoardActivityLog.IRequest,
    }),
  );

  // 8. nonsense 역할명(임의값) → 0건 반환되어야
  const nonsenseRes =
    await api.functional.discussionBoard.moderator.activityLogs.search(
      connection,
      {
        body: {
          actor_type: "NOT_A_REAL_ROLE",
          page: 1,
          limit: 10,
        } satisfies IDiscussionBoardActivityLog.IRequest,
      },
    );
  typia.assert(nonsenseRes);
  TestValidator.equals("no logs for nonsense actor_type")(
    nonsenseRes.data.length,
  )(0);
}

