import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";

/**
 * Test that members cannot add attachments to comments they do not own
 * (forbidden action).
 *
 * This test covers the following workflow:
 *
 * 1. Register two distinct board members via admin.
 * 2. First member creates a comment (as the target comment owner).
 * 3. Second member attempts to add an attachment to the first member's comment.
 * 4. Verify that the API responds with a forbidden error and prevents the
 *    unauthorized action.
 *
 * This validates business logic enforcing comment ownership on attachment
 * creation, so only the comment's author (member) may upload attachments.
 */
export async function test_api_discussionBoard_test_create_comment_attachment_forbidden_for_non_owner(
  connection: api.IConnection,
) {
  // 1. Register two distinct members
  const ownerIdentifier = RandomGenerator.alphaNumeric(10);
  const secondIdentifier = RandomGenerator.alphaNumeric(10);
  const joinedAt = new Date().toISOString();

  const ownerMember = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: ownerIdentifier,
        joined_at: joinedAt,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(ownerMember);

  const secondMember =
    await api.functional.discussionBoard.admin.members.create(connection, {
      body: {
        user_identifier: secondIdentifier,
        joined_at: joinedAt,
      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(secondMember);

  // 2. Owner creates a comment
  const postId = typia.random<string & tags.Format<"uuid">>();
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: ownerMember.id,
        discussion_board_post_id: postId,
        content: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 3. Second member attempts to add an attachment to the owner's comment
  // (Simulate as if secondMember is the authorized uploader; in a real system, this could require token/session switching)
  const attachmentInput = {
    discussion_board_comment_id: comment.id,
    uploader_member_id: secondMember.id,
    file_name: `${RandomGenerator.alphaNumeric(8)}.jpg`,
    file_url: `https://cdn.example.com/${RandomGenerator.alphaNumeric(16)}`,
    mime_type: "image/jpeg",
  } satisfies IDiscussionBoardCommentAttachment.ICreate;

  await TestValidator.error(
    "Non-owner should not be able to add attachment to another member's comment",
  )(() =>
    api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: attachmentInput,
      },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";

/**
 * Validate server-side restriction of comment attachment file types
 * (negative/positive test)
 *
 * This test ensures the system prevents attaching disallowed file types (e.g.,
 * executables) as comment attachments and allows safe types (e.g., images). It
 * verifies business rules and API-layer security checks for file type
 * enforcement.
 *
 * Steps:
 *
 * 1. Admin creates a member for use in this test.
 * 2. Member creates a comment under a (random) post.
 * 3. Member attempts to attach a disallowed file type
 *    (.exe/application/x-msdownload) to comment—API must reject.
 * 4. Member attempts an allowed file type (.png/image/png)—API must accept and
 *    return the attachment record.
 * 5. All steps assert correct business logic and strict type validation.
 */
export async function test_api_discussionBoard_test_create_comment_attachment_file_type_restriction(
  connection: api.IConnection,
) {
  // 1. Admin creates a member for the attachment test
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: RandomGenerator.alphaNumeric(12),
        joined_at: new Date().toISOString(),
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(member);

  // 2. Member creates a comment on a random post
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    {
      body: {
        discussion_board_member_id: member.id,
        discussion_board_post_id: typia.random<string & tags.Format<"uuid">>(),
        content: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardComment.ICreate,
    },
  );
  typia.assert(comment);

  // 3. Member tries to attach a disallowed file type (.exe/application/x-msdownload)
  await TestValidator.error(
    "disallowed file type: .exe/application/x-msdownload",
  )(() =>
    api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          uploader_member_id: member.id,
          file_name: "malware.exe",
          file_url: "https://cdn.example.com/malware.exe",
          mime_type: "application/x-msdownload",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    ),
  );

  // 4. Member tries to attach a permitted image file (should succeed)
  const allowed =
    await api.functional.discussionBoard.member.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: {
          discussion_board_comment_id: comment.id,
          uploader_member_id: member.id,
          file_name: "profile.png",
          file_url: "https://cdn.example.com/profile.png",
          mime_type: "image/png",
        } satisfies IDiscussionBoardCommentAttachment.ICreate,
      },
    );
  typia.assert(allowed);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";

/**
 * Validate that a moderator can attach a file to any comment, including
 * comments they did not author, verifying cross-role attachment functionality
 * and complete audit trail recording.
 *
 * This test simulates a real business scenario where a moderator may need to
 * add evidence, corrections, or externally sourced materials to a member's
 * comment for compliance, dispute resolution, or moderation.
 *
 * Steps:
 *
 * 1. Register a new board member via admin endpoint (simulate user onboarding)
 * 2. As that member, create a comment on some post (using a random post id)
 * 3. As moderator, upload a file attachment to that comment specifying yourself as
 *    uploader
 * 4. Validate the attachment response:
 *
 *    - The attachment record references the correct comment and uploader
 *    - All mandatory metadata (filename, url, mime type, uploaded_at) is present and
 *         correctly formatted
 *    - The attachment record can be traced to both the member comment and the
 *         moderator uploader id
 */
export async function test_api_discussionBoard_test_create_comment_attachment_as_moderator(
  connection: api.IConnection,
) {
  // 1. Register a new board member via admin endpoint (simulate user onboarding)
  const memberUserIdentifier = typia.random<string>();
  const memberJoinTime = new Date().toISOString();
  const member = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: memberUserIdentifier,
        joined_at: memberJoinTime,
      },
    },
  );
  typia.assert(member);

  // 2. As that member, create a comment (use a random post id for the test)
  const postId = typia.random<string & tags.Format<"uuid">>();
  const commentBody: IDiscussionBoardComment.ICreate = {
    discussion_board_member_id: member.id,
    discussion_board_post_id: postId,
    content: RandomGenerator.paragraph()(),
  };
  const comment = await api.functional.discussionBoard.member.comments.create(
    connection,
    { body: commentBody },
  );
  typia.assert(comment);

  // 3. As moderator, attach a file to the comment (simulate moderator id as uploader)
  // We'll generate a new moderator record to simulate this, or reuse the member id if no explicit moderator session switching is available.
  const moderatorUserIdentifier = typia.random<string>();
  const moderatorJoinTime = new Date().toISOString();
  const moderator = await api.functional.discussionBoard.admin.members.create(
    connection,
    {
      body: {
        user_identifier: moderatorUserIdentifier,
        joined_at: moderatorJoinTime,
      },
    },
  );
  typia.assert(moderator);

  const attachmentInput: IDiscussionBoardCommentAttachment.ICreate = {
    discussion_board_comment_id: comment.id,
    uploader_member_id: moderator.id,
    file_name: RandomGenerator.alphabets(10) + ".txt",
    file_url: `https://cdn.example.com/${RandomGenerator.alphaNumeric(16)}`,
    mime_type: "text/plain",
  };
  const attachment =
    await api.functional.discussionBoard.moderator.comments.attachments.create(
      connection,
      {
        commentId: comment.id,
        body: attachmentInput,
      },
    );
  typia.assert(attachment);

  // 4. Validate
  //   a. The attachment's comment id and uploader id match the intended ones
  TestValidator.equals("attachment references correct comment")(
    attachment.discussion_board_comment_id,
  )(comment.id);
  TestValidator.equals("attachment uploader is moderator")(
    attachment.uploader_member_id,
  )(moderator.id);
  //   b. File metadata is present and correctly formatted
  TestValidator.equals("file_name matches")(attachment.file_name)(
    attachmentInput.file_name,
  );
  TestValidator.equals("file_url matches")(attachment.file_url)(
    attachmentInput.file_url,
  );
  TestValidator.equals("mime_type matches")(attachment.mime_type)(
    attachmentInput.mime_type,
  );
  //   c. uploaded_at is a valid ISO8601 string
  TestValidator.predicate("uploaded_at is ISO8601 date")(
    !isNaN(Date.parse(attachment.uploaded_at)),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardCommentAttachment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardCommentAttachment";

/**
 * Test moderator's attempt to upload an attachment to a non-existent comment.
 *
 * This scenario ensures that even moderator roles cannot attach files to
 * comments that do not exist. It verifies the backend strictly enforces comment
 * existence as a parent for attachments.
 *
 * The test tries to upload a file by providing a random (guaranteed
 * non-existent) commentId. The expected behavior is a runtime error (such as
 * HTTP 404 Not Found or similar business error) indicating the parent comment
 * was not found. Any acceptance of the upload indicates a critical bug in
 * reference integrity enforcement.
 *
 * Workflow:
 *
 * 1. Construct a random UUID for commentId that cannot correspond to an actual
 *    comment (no prior comment creation step).
 * 2. Prepare attachment upload input with random but valid-looking data for a
 *    file, specifying the above non-existent commentId as parent.
 * 3. Call the API as a moderator, attempting the upload.
 * 4. Assert that an error is thrown due to missing parent comment (error catch
 *    block/test validator).
 */
export async function test_api_discussionBoard_test_create_comment_attachment_as_moderator_on_nonexistent_comment(
  connection: api.IConnection,
) {
  // Step 1: Prepare a random non-existent comment ID (UUID format)
  const nonExistentCommentId = typia.random<string & tags.Format<"uuid">>();

  // Step 2: Build upload request body. Use valid dummy data, but reference the non-existent commentId
  const uploaderMemberId = typia.random<string & tags.Format<"uuid">>();
  const fileName = `testfile_${Date.now()}.jpg`;
  const fileUrl = `https://cdn.example.com/fakepath/${Date.now()}_sample.jpg`;
  const mimeType = "image/jpeg";
  const input: IDiscussionBoardCommentAttachment.ICreate = {
    discussion_board_comment_id: nonExistentCommentId,
    uploader_member_id: uploaderMemberId,
    file_name: fileName,
    file_url: fileUrl,
    mime_type: mimeType,
  };

  // Step 3: Attempt the upload, expecting an error (not found)
  await TestValidator.error("Upload should fail due to missing parent comment")(
    async () => {
      await api.functional.discussionBoard.moderator.comments.attachments.create(
        connection,
        {
          commentId: nonExistentCommentId,
          body: input,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
