    api.functional.discussionBoard.admin.guests.search(connection, {
      body: { page: -10 },
    }),
  );

  // 2. Non-integer page (should fail type constraints)
  await TestValidator.error("string as page index should fail")(() =>
    api.functional.discussionBoard.admin.guests.search(connection, {
      body: { page: "1" as any },
    }),
  );

