import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 시스템(글로벌 및 카테고리별) 공지사항 등록 E2E 검증.
 *
 * 어드민 사용자가 유효한 데이터(제목, 본문, is_active, 선택적 category_id, start_at, end_at)를 포함하여
 * 시스템 공지사항을 생성할 수 있는지 검증합니다.
 *
 * 1. 활성화 상태(즉시 노출) 공지 등록 및 반환값/메타 검증
 * 2. 카테고리+스케줄 조합 공지 등록 및 필드 일치 확인
 * 3. 숨김(is_active: false) 상태 공지 등록 및 비노출 속성 확인
 *
 * - 각 notice 마다: 반환된 UUID, created/updated date, 입력 필드 반영, 포맷 및 result값 검증
 */
export async function test_api_discussionBoard_admin_systemNotices_create(
  connection: api.IConnection,
) {
  // 1. 활성화(즉시 노출) 공지 등록
  const createInput1: IDiscussionBoardSystemNotice.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
    is_active: true,
    category_id: null,
    start_at: null,
    end_at: null,
  };
  const notice1 =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body: createInput1 },
    );
  typia.assert(notice1);
  TestValidator.equals("공지 제목 일치")(notice1.title)(createInput1.title);
  TestValidator.equals("공지 본문 일치")(notice1.body)(createInput1.body);
  TestValidator.equals("is_active TRUE")(notice1.is_active)(true);
  TestValidator.equals("카테고리 null")(notice1.category_id)(null);
  TestValidator.equals("시작시각 null")(notice1.start_at)(null);
  TestValidator.equals("종료시각 null")(notice1.end_at)(null);
  TestValidator.predicate("id(uuid) 포맷")(notice1.id.length === 36);
  TestValidator.predicate("생성/수정시각 존재")(
    !!notice1.created_at && !!notice1.updated_at,
  );

  // 2. 카테고리 및 스케줄 등록 케이스 (start/end 타임 활용)
  const catId = typia.random<string & tags.Format<"uuid">>();
  const start_at = new Date(Date.now() + 60 * 60 * 1000).toISOString(); // 1시간 후
  const end_at = new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString(); // 2시간 후
  const createInput2: IDiscussionBoardSystemNotice.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
    is_active: true,
    category_id: catId,
    start_at,
    end_at,
  };
  const notice2 =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body: createInput2 },
    );
  typia.assert(notice2);
  TestValidator.equals("카테고리 적용")(notice2.category_id)(catId);
  TestValidator.equals("start_at")(notice2.start_at)(start_at);
  TestValidator.equals("end_at")(notice2.end_at)(end_at);
  TestValidator.equals("is_active TRUE")(notice2.is_active)(true);

  // 3. 숨김(비노출) 상태 공지 등록
  const createInput3: IDiscussionBoardSystemNotice.ICreate = {
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
    is_active: false,
    category_id: null,
    start_at: null,
    end_at: null,
  };
  const notice3 =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      { body: createInput3 },
    );
  typia.assert(notice3);
  TestValidator.equals("is_active FALSE")(notice3.is_active)(false);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * Validate failure on creating a system notice with invalid category reference.
 *
 * This test verifies that when an admin attempts to create a system notice
 * (global or category-scoped announcement) with a category_id that does not
 * exist, the API correctly rejects the request and produces an error.
 *
 * Test Flow:
 *
 * 1. Attempt to create a system notice with a non-existent (random) category_id
 *    (valid format UUID but no such category exists).
 * 2. Expect the API to return an error (e.g., 400/404) indicating invalid
 *    category.
 * 3. Ensure no system notice is created as a result (no valid notice object
 *    returned).
 */
export async function test_api_discussionBoard_admin_systemNotices_create_with_invalid_category(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for non-existent category_id
  const invalidCategoryId: string = typia.random<
    string & tags.Format<"uuid">
  >();

  // 2. Build the notice creation input with the invalid category
  const noticeInput: IDiscussionBoardSystemNotice.ICreate = {
    category_id: invalidCategoryId, // Deliberate invalid reference
    title: "Test Invalid Category",
    body: "This notice should not succeed.",
    is_active: true,
    // start_at, end_at can be omitted (optional)
  };

  // 3. Attempt to create the notice and assert that it fails
  await TestValidator.error("should fail for invalid category_id")(async () => {
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: noticeInput,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 시스템 공지사항 생성 시 카테고리 내 제목의 유일성을 검증한다.
 *
 * - 기본적으로 공지 제목은 같은 카테고리 내에서 중복을 허용하지 않아야 한다. (글로벌 공지/타 카테고리는 별개로 취급)
 *
 * 테스트 플로우:
 *
 * 1. 하나의 카테고리(category_id)와 특정 제목(title)으로 공지A를 등록한다.
 * 2. 같은 카테고리(category_id)와 같은 제목(title)으로 공지B 재생성 시도 → 반드시 에러(Business validation
 *    error) 발생해야 한다.
 * 3. 다른 카테고리(anotherCategoryId)로 같은 제목(title) 공지 등록 → 정상적으로 등록 성공
 * 4. 첫번째 카테고리(category_id)에 다른 제목(title + "-V2")으로 공지 등록 → 정상적으로 등록 성공
 */
export async function test_api_discussionBoard_admin_systemNotices_test_create_system_notice_with_duplicate_title_in_category(
  connection: api.IConnection,
) {
  // 1. 최초 공지 등록 (category_id, title)
  const categoryId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const title = "UniqTitle-" + RandomGenerator.alphaNumeric(10);
  const body = RandomGenerator.paragraph()();

  const firstNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: categoryId,
          title,
          body,
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(firstNotice);
  TestValidator.equals("category match")(firstNotice.category_id)(categoryId);
  TestValidator.equals("title match")(firstNotice.title)(title);

  // 2. 같은 category + 같은 title → 실패 (expect error)
  await TestValidator.error("duplicate title in same category should fail")(
    async () => {
      await api.functional.discussionBoard.admin.systemNotices.create(
        connection,
        {
          body: {
            category_id: categoryId,
            title,
            body: body + " (copy)",
            is_active: true,
          } satisfies IDiscussionBoardSystemNotice.ICreate,
        },
      );
    },
  );

  // 3. 다른 category + 같은 title → 성공
  const anotherCategoryId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const secondNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: anotherCategoryId,
          title,
          body,
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(secondNotice);
  TestValidator.equals("category match")(secondNotice.category_id)(
    anotherCategoryId,
  );
  TestValidator.equals("title match")(secondNotice.title)(title);

  // 4. 같은 category + 다른 title → 성공
  const thirdNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: categoryId,
          title: title + "-V2",
          body,
          is_active: true,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(thirdNotice);
  TestValidator.equals("category match")(thirdNotice.category_id)(categoryId);
  TestValidator.equals("title match")(thirdNotice.title)(title + "-V2");
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 시스템 공지사항의 필드 수정(관리자 권한) API를 검증합니다.
 *
 * 이 테스트는 관리자 계정이 기존의 시스템 공지를 UUID 기준으로 찾아서, 주요 필드(제목, 본문, 활성화 여부, 스케줄, 카테고리 등)를
 * 변경할 수 있음을 보장합니다. 생성된 공지는 실제로 수정 요청 이후 조회 시 변경사항이 반영되어야 하며, 공지 목록 내에서도 즉시
 * 갱신되어야 합니다(목록 조회 API는 제공되지 않으므로 직접 조회로 확인).
 *
 * 주요 검증 절차는 다음과 같습니다:
 *
 * 1. 선행: 시스템 공지 1건을 등록(생성)합니다
 * 2. 공지의 여러 필드를 업데이트합니다(title, body, is_active, start_at, end_at, category_id 등)
 * 3. API의 응답이 변경사항을 반영했는지 확인합니다
 * 4. 동일 공지를 재조회하여 필드 업데이트가 실제로 반영됐는지 검증합니다(목록조회 생략).
 * 5. 불가능한 값(ex. end_at이 start_at보다 과거인 경우), 중복제목 등 유효성/비즈니스 검사 케이스도 함께 확인합니다(고의
 *    실패).
 */
export async function test_api_discussionBoard_admin_systemNotices_test_update_system_notice_fields_as_admin(
  connection: api.IConnection,
) {
  // 1. 시스템 공지 1건을 생성(의존성)
  const initialNotice: IDiscussionBoardSystemNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "공지 타이틀 - 최초등록",
          body: "초기 공지 내용입니다. (e2e 등록)",
          is_active: true,
          category_id: null,
          start_at: null,
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(initialNotice);

  // 2. 여러 필드 수정값 준비 (카테고리 부여, 타이틀 변경, 본문/스케줄 및 활성화 반전 등)
  const updateDto: IDiscussionBoardSystemNotice.IUpdate = {
    title: "공지 타이틀 수정 - 카테고리 부여",
    body: "수정된 공지 내용입니다.",
    is_active: false,
    category_id: typia.random<string & tags.Format<"uuid">>(),
    start_at: new Date(Date.now() + 10 * 60 * 1000).toISOString(), // 10분 후
    end_at: new Date(Date.now() + 100 * 60 * 1000).toISOString(), // 100분 후
  };

  // 3. update API 실행
  const updatedNotice: IDiscussionBoardSystemNotice =
    await api.functional.discussionBoard.admin.systemNotices.update(
      connection,
      {
        systemNoticeId: initialNotice.id,
        body: updateDto,
      },
    );
  typia.assert(updatedNotice);

  // 4. 값 반영 확인
  TestValidator.equals("title")(updatedNotice.title)(updateDto.title);
  TestValidator.equals("body")(updatedNotice.body)(updateDto.body);
  TestValidator.equals("카테고리")(updatedNotice.category_id)(
    updateDto.category_id,
  );
  TestValidator.equals("is_active")(updatedNotice.is_active)(
    updateDto.is_active,
  );
  TestValidator.equals("start_at")(updatedNotice.start_at)(updateDto.start_at);
  TestValidator.equals("end_at")(updatedNotice.end_at)(updateDto.end_at);

  // 5. 불가능 케이스: end_at이 start_at보다 과거면 실패
  const failUpdate: IDiscussionBoardSystemNotice.IUpdate = {
    title: "타이틀 실패 케이스",
    body: "잘못된 스케줄 케이스",
    is_active: true,
    end_at: updateDto.start_at,
    start_at: updateDto.end_at, // start > end
    category_id: updateDto.category_id,
  };
  await TestValidator.error("역순 스케줄 업데이트 불가")(async () => {
    await api.functional.discussionBoard.admin.systemNotices.update(
      connection,
      {
        systemNoticeId: initialNotice.id,
        body: failUpdate,
      },
    );
  });

  // 6. 불가능 케이스: 동일 카테고리 내 타이틀 중복 등록은 불가
  // (다른 공지를 생성하고 해당 카테고리·타이틀로 update 시도)
  const anotherNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "중복체크 타이틀",
          body: "또다른 공지",
          is_active: true,
          category_id: updateDto.category_id,
          start_at: null,
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(anotherNotice);

  await TestValidator.error("같은 카테고리 내 타이틀 중복 방지")(async () => {
    await api.functional.discussionBoard.admin.systemNotices.update(
      connection,
      {
        systemNoticeId: anotherNotice.id,
        body: { ...updateDto, title: "중복체크 타이틀" },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * Validate that updating a system notice with an invalid scheduling window
 * fails.
 *
 * This test ensures the API rejects schedule updates where start_at > end_at
 * (start after end), returning a validation error when an admin attempts such
 * an update. It also verifies that, on failure, the notice record is NOT
 * modified (as far as the API contract allows; since no "get by ID" API exists,
 * post-check is omitted).
 *
 * Test Outline:
 *
 * 1. Create a valid system notice
 * 2. Attempt to update it with start_at after end_at (invalid window)
 * 3. Assert the update API call throws an error for scheduling logic violation
 *
 * Note: There is no system-notice get-by-id API to verify the notice is
 * unchanged; that part is skipped.
 */
export async function test_api_discussionBoard_admin_systemNotices_test_update_system_notice_with_invalid_schedule(
  connection: api.IConnection,
) {
  // 1. Create a valid system notice
  const originalNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          title: "Invalid Update Test - System Notice",
          body: "Schedule logic negative test.",
          is_active: true,
          start_at: null,
          end_at: null,
          category_id: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(originalNotice);

  // 2. Prepare invalid window: start_at after end_at
  const now = new Date();
  const startAt = new Date(now.getTime() + 60 * 60 * 1000).toISOString(); // +1 hour
  const endAt = new Date(now.getTime() - 60 * 60 * 1000).toISOString(); // -1 hour

  // 3. Try the invalid update and expect a validation error
  await TestValidator.error("invalid scheduling window should fail")(() =>
    api.functional.discussionBoard.admin.systemNotices.update(connection, {
      systemNoticeId: originalNotice.id,
      body: {
        title: originalNotice.title,
        body: originalNotice.body,
        is_active: originalNotice.is_active,
        start_at: startAt,
        end_at: endAt,
        category_id: originalNotice.category_id ?? null,
      } satisfies IDiscussionBoardSystemNotice.IUpdate,
    }),
  );
  // 4. No get-by-id API available to verify unchanged state, so post-check is omitted.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardSystemNotice } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardSystemNotice";

/**
 * 시스템(공지사항) 삭제의 관리자 기능을 검증합니다.
 *
 * - 관리자(admin)가 특정 시스템 공지사항을 UUID로 영구 삭제할 수 있는지 테스트합니다.
 * - 1. 새로운 공지사항을 생성 2) 해당 UUID로 DELETE 수행 3) 삭제 완료까지를 확인합니다.
 *
 * 테스트 시나리오
 *
 * 1. 시스템 공지사항을 테스트용으로 새로 생성합니다.
 * 2. 생성된 시스템 공지사항의 UUID(systemNoticeId)로 삭제(erase) API 호출
 * 3. (삭제 후 개별 조회 API가 없으므로 불가역성 및 예외확인은 생략)
 *
 * 이 테스트는 시스템 공지사항의 완전 삭제(불가역성, API 노출 범위까지)를 검증합니다.
 */
export async function test_api_discussionBoard_admin_systemNotices_erase(
  connection: api.IConnection,
) {
  // 1. 시스템 공지사항 생성(테스트 전용)
  const systemNotice =
    await api.functional.discussionBoard.admin.systemNotices.create(
      connection,
      {
        body: {
          category_id: null, // 전역 공지 (카테고리 지정 필요시 UUID 활용 가능)
          title: RandomGenerator.paragraph()(1),
          body: RandomGenerator.content()(1)(2),
          is_active: true,
          start_at: null,
          end_at: null,
        } satisfies IDiscussionBoardSystemNotice.ICreate,
      },
    );
  typia.assert(systemNotice);

  // 2. 생성한 공지사항 UUID를 사용해 영구 삭제
  await api.functional.discussionBoard.admin.systemNotices.erase(connection, {
    systemNoticeId: systemNotice.id,
  });
  // 3. (삭제 후 별도의 GET API가 제공되지 않아 조회 및 404확인은 불가)
}

