          post_id: post.id,
          flag_type: "spam",
          flag_source: "manual",
          flagged_by_moderator_id: moderator.id,
          flag_details: "Initial flag for negative test.",
        },
      },
    );
  typia.assert(flag);

  // 4. Attempt invalid update scenarios

